window.AUTH=window.AUTH||{};window.AUTH["18-1023"]={"d":"18-1023","id":"2019/18-1023","n":"Maine Community Health Options v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Maine Community Health Options","date":"2019-08-30","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/114323/20190830144530676_18-1023ts.pdf","side":"pet","n":61},{"k":"petitioner","label":"Brief of petitioner Land of Lincoln Mutual Health Insurance Company","date":"2019-08-30","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/114267/20190830124053503_18-1023%20ts%20Land%20of%20Lincoln.pdf","side":"pet","n":72},{"k":"petitioner","label":"Brief of petitioners Moda Health Plan, Inc., and Blue Cross and Blue Shield of North Carolina","date":"2019-08-30","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/114320/20190830143120987_18-1028%20Brief%20for%20Petitioners.pdf","side":"pet","n":56},{"k":"respondent","label":"Brief of respondent United States","date":"2019-10-21","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/119724/20191021193212221_18-1023bsUnitedStates.pdf","side":"res","n":91},{"k":"reply","label":"Reply of petitioner Maine Community Health Options","date":"2019-11-19","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/122922/20191119141716260_18-1023rb.pdf","side":"pet","n":30},{"k":"reply","label":"Reply of petitioner Moda Health Plan, Inc.","date":"2019-11-20","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/123086/20191120125558779_2019-11-20%20Moda%20Merits%20Reply%20FINAL.pdf","side":"pet","n":29},{"k":"reply","label":"Reply of petitioner Land of Lincoln Mutual Health Insurance Company","date":"2019-11-20","url":"https://www.supremecourt.gov/DocketPDF/18/18-1023/123168/20191120163457697_18-1038rb.pdf","side":"pet","n":64}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US1PP_web.pdf#page=312","tr":true,"items":[{"t":"case","label":"Agwiak v. United States","cite":"347 F.3d 1375","y":2003,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/347/1375/","by":{"0":"25"}},{"t":"case","label":"Alpine PCS, Inc. v. United States","cite":"878 F.3d 1086","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/878/1086/","by":{"0":"26","4":"20"}},{"t":"case","label":"Bowen v. Massachusetts","cite":"487 U.S. 879","y":1988,"id":"1987/87-712","sc":1,"op":7,"sum":"Rejecting cause of action cognizable under the Tucker Act based on “shall pay” requirement under the Medicaid Act, 42 U. S. C. § 1396b(a).","sumSrc":"opinion","by":{"0":"24, 25, 26","3":"31, 32, 33","4":"19, 20, 21, 22","5":"20","6":"20, 21"}},{"t":"case","label":"Branch v. Smith","cite":"538 U.S. 254","y":2003,"id":"2002/01-1437","sc":1,"sum":"The Court held, 9-0, that the District Court properly enjoined enforcement of the state- court plan that lacked the required timely preclearance.","sumSrc":"Oyez","by":{"0":"43","1":"22"}},{"t":"case","label":"Collins v. United States","cite":"15 Ct. Cl. 22","y":1879,"url":"https://www.courtlistener.com/c/Ct.%20Cl./15/22/","by":{"0":"31, 32"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"548 U.S. 30","y":2006,"id":"2005/04-1376","sc":1,"sum":"The Court ruled that the reinstatement statute does apply to illegal aliens who re-entered the U.S. before the effective date of the statute, and that the application to such aliens was not impermissibly retroactive.","sumSrc":"Oyez","by":{"0":"45","3":"51, 52"}},{"t":"case","label":"Ferris v. United States","cite":"27 Ct. Cl. 542","y":1892,"url":"https://www.courtlistener.com/c/Ct.%20Cl./27/542/","op":1,"by":{"0":"33, 36, 54","1":"27","2":"30","3":"33","4":"6, 7","5":"13"}},{"t":"case","label":"Fisher v. United States","cite":"402 F.3d 1167","y":2005,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/402/1167/","op":4,"by":{"0":"26","3":"33"}},{"t":"case","label":"Gibney v. United States","cite":"114 Ct. Cl. 38","y":1949,"url":"https://www.courtlistener.com/c/Ct.%20Cl./114/38/","by":{"0":"31"}},{"t":"case","label":"Graham v. United States","cite":"1 Ct. Cl. 380","y":1865,"url":"https://www.courtlistener.com/c/Ct.%20Cl./1/380/","by":{"0":"37"}},{"t":"case","label":"Greenlee Cty., Ariz. v. United States","cite":"487 F.3d 871","y":2007,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/487/871/","op":1,"by":{"0":"25, 28","3":"33","4":"12, 19","5":"15","6":"5, 13"}},{"t":"case","label":"Highland Falls-Fort Montgomery Cent. Sch. Dist. v. United States","cite":"48 F.3d 1166","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/48/1166/","op":3,"by":{"0":"28","3":"26, 27, 39","4":"12, 17, 18","5":"15, 16","6":"13, 14"}},{"t":"case","label":"J.E.M. Ag Supply, Inc. v. Pioneer Hi-Bred Int’l, Inc.","cite":"534 U.S. 124","y":2001,"id":"2001/99-1996","sc":1,"op":1,"sum":"The Court held that utility patents may be issued for plants.","sumSrc":"Oyez","by":{"0":"43","1":"22"}},{"t":"case","label":"Landgraf. v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"op":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41, 45, 47","1":"43","2":"34, 47"}},{"t":"case","label":"Miller v. United States","cite":"86 Ct. Cl. 609","y":1938,"url":"https://www.courtlistener.com/c/Ct.%20Cl./86/609/","by":{"0":"37"}},{"t":"case","label":"Moda Health Plan, Inc. v. United States","cite":"892 F.3d 1311","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/892/1311/","op":8,"by":{"0":"passim","1":"1","4":"4"}},{"t":"case","label":"Moda Health Plan, Inc. v. United States","cite":"908 F.3d 738","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/908/738/","op":1,"by":{"0":"passim","1":"1"}},{"t":"case","label":"Molina Healthcare of Cal. Inc. v. United States","cite":"133 Fed. Cl. 14","y":2017,"url":"https://www.courtlistener.com/c/Fed.%20Cl./133/14/","by":{"0":"46","3":"24","5":"11"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"op":3,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"0":"39, 43","2":"28","3":"25"}},{"t":"case","label":"N.Y. Airways, Inc. v. United States","cite":"369 F.2d 743","y":1966,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/369/743/","op":1,"by":{"0":"36","1":"28, 51","3":"33","6":"13, 16, 24"}},{"t":"case","label":"Parsons v. United States","cite":"15 Ct. Cl. 246","y":1879,"url":"https://www.courtlistener.com/c/Ct.%20Cl./15/246/","by":{"0":"37"}},{"t":"case","label":"Posadas v. Nat’l City Bank of N.Y.","cite":"296 U.S. 497","y":1936,"id":"scdb/1935-071","sc":1,"by":{"0":"38, 41, 43","2":"22"}},{"t":"case","label":"Prairie Cty., Mont. v. United States","cite":"113 Fed. Cl. 194","y":2013,"url":"https://www.courtlistener.com/c/Fed.%20Cl./113/194/","by":{"0":"28","4":"12"}},{"t":"case","label":"Salazar v. Ramah Navajo Chapter","cite":"567 U.S. 182","y":2012,"id":"2011/11-551","sc":1,"op":2,"sum":"The Court held that, under the Indian Self-Determination and Education Assistance Act, the government is required to pay all of the contract support costs incurred by a tribal contractor if payment of those costs would exceed the statutory cap on the appropriations available to pay them.","sumSrc":"Oyez","by":{"0":"passim","1":"27, 28, 46, 48","2":"24, 30, 35, 57","3":"36, 37, 38, 39, 40","4":"6, 9, 12","5":"passim","6":"passim"}},{"t":"case","label":"Slattery v. United States","cite":"635 F.3d 1298","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/635/1298/","by":{"0":"30","3":"33","4":"7","5":"15"}},{"t":"case","label":"Strong v. United States","cite":"60 Ct. Cl. 627","y":1925,"url":"https://www.courtlistener.com/c/Ct.%20Cl./60/627/","by":{"0":"37","4":"6"}},{"t":"case","label":"Tenn. Valley Auth. v. Hill","cite":"437 U.S. 153","y":1978,"id":"1977/76-1701","sc":1,"sum":"The Supreme Court held that Congress’ continued appropriation of funds did not imply that the Dam project was exempt from the ESA. The operation of the Tellico Dam would wipe out the Snail Darter's habitat, so an injunction was the proper remedy.","sumSrc":"Oyez","by":{"0":"42","1":"22, 36","2":"passim","3":"51","5":"3"}},{"t":"case","label":"United States Fid. & Guar. Co. v. United States","cite":"209 U.S. 306","y":1908,"id":"scdb/1907-146","sc":1,"sum":"There is always a strong presumption that a statute was not meant to act retrospectively, and it should never receive such a construction if susceptible of any other, nor unless the words are so clear, strong and imperative as to have no other meaning.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"45","2":"47"}},{"t":"case","label":"United States v. Bormes","cite":"568 U.S. 6","y":2012,"id":"2012/11-192","sc":1,"op":6,"sum":"The Court held that the Little Tucker Act does not apply to lawsuits brought under the Federal Credit Reporting Act.","sumSrc":"Oyez","by":{"0":"26","3":"19, 20","4":"20, 22"}},{"t":"case","label":"United States v. Dickerson","cite":"310 U.S. 554","y":1940,"id":"scdb/1939-059","sc":1,"op":4,"ar":3,"sum":"1. A proviso appended to an appropriation in § 402 of Public Resolution 122, June 21, 1938, declared \"no part of any appropriation contained in this or any other Act for the fiscal year ending June 30, 1939, shall be available for the payment\" of any enlistment aI-, lowance for \"re-enlistments made during the fiscal year ending June 30, 1939, notwithstanding applicable portions of sections 9 and 10\" of the basic …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50, 51","1":"passim","2":"passim","3":"44, 47","5":"4, 15","6":"22"}},{"t":"case","label":"United States v. Hansen","cite":"772 F.2d 940","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/772/940/","by":{"0":"42"}},{"t":"case","label":"United States v. Langston","cite":"118 U.S. 389","y":1886,"id":"scdb/1885-272","sc":1,"op":11,"ar":5,"sum":"A statute which fixes the annual salary of a public officer at a designated sum without limitation as to time, is not abrogated or suspended by subsequent enactments appropriating a less amount for his services for a particular fiscal year, but containing no words which expressly or impliedly modify or repeal it.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30, 39, 40, 49","1":"passim","2":"passim","3":"27, 30, 31, 49, 50","4":"4, 16, 17","5":"3, 10, 14","6":"passim"}},{"t":"case","label":"United States v. Mitchell","cite":"109 U.S. 146","y":1883,"id":"scdb/1883-024","sc":1,"op":5,"sum":"Interpreter — Salary—Statute.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"passim","1":"passim","2":"passim","3":"44"}},{"t":"case","label":"United States v. Mitchell","cite":"463 U.S. 206","y":1983,"id":"1982/81-1748","sc":1,"op":6,"sum":"The United States is accountable in money damages for alleged breaches of trust in connection with its management of forest resources on allotted lands of the Quinault Reservation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 26","4":"18, 19","5":"15","6":"19"}},{"t":"case","label":"x United States v. St. Louis, S.F. & T.Ry. Co.","cite":"270 U.S. 1","y":1926,"id":"scdb/1925-177","sc":1,"sum":"not applicable retroactively to causes of action existing at the date of the Transportation Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"United States v. Testan","cite":"424 U.S. 392","y":1976,"id":"1975/74-753","sc":1,"op":5,"sum":"Respondent Government trial attorneys with civil service grade GS-13 classifications requested their employing agency to reclassify their positions to grade GS-14, contending that their duties and responsibilities met the requirements for the higher grade and were identical to those of other trial attorneys classified as GS-14 in another agency, and that under the principle of \"equal pay for substantially equal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","4":"5, 18, 19"}},{"t":"case","label":"United States v. Vulte","cite":"233 U.S. 509","y":1914,"id":"scdb/1913-145","sc":1,"op":9,"sum":"A statute which fixes the annual salary of a public officer at a designated sum without limitation as to time is not abrogated or suspended by subsequent enactments which merely appropriate a less amount for that officer for particular years and which contain no words expressly, or by clear implication, modifying or repealing the previous law. United States v. Langston, 118 U. S. 389.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"49","1":"passim","2":"28, 29, 30, 31","3":"50","6":"24"}},{"t":"case","label":"United States v. Will","cite":"449 U.S. 200","y":1980,"id":"1980/79-983","sc":1,"op":6,"ar":4,"sum":"In two of the years in question, Congress effectively revoked automatic pay increases after the statutes guaranteeing those increases had already taken effect. This amounted to a reduction in salaries for judges and violated the Compensation Clause.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"44, 46, 47","5":"4, 15","6":"22"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3","1":"2"}},{"t":"usc","label":"28 U.S.C. § 1295","url":"https://www.law.cornell.edu/uscode/text/28/1295","subs":["(a)(3)"],"by":{"0":"3","1":"1"}},{"t":"usc","label":"28 U.S.C. § 1491","url":"https://www.law.cornell.edu/uscode/text/28/1491","subs":["(a)","(a)(1)"],"stext":{"head":"§1491. Claims against United States generally; actions involving Tennessee Valley Authority","paras":[[0,"(a)(1) The United States Court of Federal Claims shall have jurisdiction to render judgment upon any claim against the United States founded either upon the Constitution, or any Act of Congress or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(2) To provide an entire remedy and to complete the relief afforded by the judgment, the court may, as an incident of and collateral to any such judgment, issue orders directing restoration to office or position, placement in appropriate duty or retirement status, and correction of applicable records, and such orders may be issued to any appropriate official of the United States. In any case within its jurisdiction, the court shall have the power to remand appropriate matters to any administrative or executive body or official with such direction as it may deem proper and just. The Court of Federal Claims shall have jurisdiction to render judgment upon any claim by or against, or dispute with, a contractor arising under section 7104(b)(1) of title 41, including a dispute concerning termination of a contract, rights in tangible or intangible property, compliance with cost accounting standards, and other nonmonetary disputes on which a decision of the contracting officer has been issued under section 6 1 of that Act."],[0,"(b)(1) Both the Unites 2 States Court of Federal Claims and the district courts of the United States shall have jurisdiction to render judgment on an action by an interested party objecting to a solicitation by a Federal agency for bids or proposals for a proposed contract or to a proposed award or the award of a contract or any alleged violation of statute or regulation in connection with a procurement or a proposed procurement. Both the United States Court of Federal Claims and the district courts of the United States shall have jurisdiction to entertain such an action without regard to whether suit is instituted before or after the contract is awarded."],[0,"(2) To afford relief in such an action, the courts may award any relief that the court considers proper, including declaratory and injunctive relief except that any monetary relief shall be limited to bid preparation and proposal costs."],[0,"(3) In exercising jurisdiction under this subsection, the courts shall give due regard to the interests of national defense and national security and the need for expeditious resolution of the action."],[0,"(4) In any action under this subsection, the courts shall review the agency's decision pursuant to the standards set forth in section 706 of title 5."],[0,"(5) If an interested party who is a member of the private sector commences an action described in paragraph (1) with respect to a public-private competition conducted under Office of Management and Budget Circular A–76 regarding the performance of an activity or function of a Federal agency, or a decision to convert a function performed by Federal employees to private sector performance without a competition under Office of Management and Budget Circular A–76, then an interested party described in section 3551(2)(B) of title 31 shall be entitled to intervene in that action."],[0,"(6) Jurisdiction over any action described in paragraph (1) arising out of a maritime contract, or a solicitation for a proposed maritime contract, shall be governed by this section and shall not be subject to the jurisdiction of the district courts of the United States under the Suits in Admiralty Act (chapter 309 of title 46) or the Public Vessels Act (chapter 311 of title 46)."],[0,"(c) Nothing herein shall be construed to give the United States Court of Federal Claims jurisdiction of any civil action within the exclusive jurisdiction of the Court of International Trade, or of any action against, or founded on conduct of, the Tennessee Valley Authority, or to amend or modify the provisions of the Tennessee Valley Authority Act of 1933 with respect to actions by or against the Authority."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1491?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1491. Claims against United States generally; actions involving Tennessee Valley Authority","tname":"Judiciary and Judicial Procedure","by":{"0":"3, 16, 21, 25","1":"1","3":"30, 49, 30, 49","4":"passim"}},{"t":"usc","label":"28 U.S.C. § 2517","url":"https://www.law.cornell.edu/uscode/text/28/2517","subs":["(b)"],"by":{"0":"32"}},{"t":"usc","label":"31 U.S.C. § 1304","url":"https://www.law.cornell.edu/uscode/text/31/1304","subs":["(a)"],"stext":{"head":"§1304. Judgments, awards, and compromise settlements","paras":[[0,"(a) Necessary amounts are appropriated to pay final judgments, awards, compromise settlements, and interest and costs specified in the judgments or otherwise authorized by law when—"],[1,"(1) payment is not otherwise provided for;"],[1,"(2) payment is certified by the Secretary of the Treasury; and"],[1,"(3) the judgment, award, or settlement is payable—"],[2,"(A) under section 2414, 2517, 2672, or 2677 of title 28;"],[2,"(B) under section 3723 of this title;"],[2,"(C) under a decision of a board of contract appeals; or"],[2,"(D) in excess of an amount payable from the appropriations of an agency for a meritorious claim under section 2733, 2733a, or 2734 of title 10, section 715 of title 32, or section 20113 of title 51."],[0,"(b)(1) Interest may be paid from the appropriation made by this section—"],[1,"(A) on a judgment of a district court, only when the judgment becomes final after review on appeal or petition by the United States Government, and then only from the date of filing of the transcript of the judgment with the Secretary of the Treasury through the day before the date of the mandate of affirmance; or"],[1,"(B) on a judgment of the Court of Appeals for the Federal Circuit or the United States Court of Federal Claims under section 2516(b) of title 28, only from the date of filing of the transcript of the judgment with the Secretary of the Treasury through the day before the date of the mandate of affirmance."],[0,"(2) Interest payable under this subsection in a proceeding reviewed by the Supreme Court is not allowed after the end of the term in which the judgment is affirmed."],[0,"(c)(1) A judgment or compromise settlement against the Government shall be paid under this section and sections 2414, 2517, and 2518 1 of title 28 when the judgment or settlement arises out of an express or implied contract made by—"],[1,"(A) the Army and Air Force Exchange Service;"],[1,"(B) the Navy Exchanges;"],[1,"(C) the Marine Corps Exchanges;"],[1,"(D) the Coast Guard Exchanges; or"],[1,"(E) the Exchange Councils of the National Aeronautics and Space Administration."],[0,"(2) The Exchange making the contract shall reimburse the Government for the amount paid by the Government."],[0,"(d) Beginning not later than the date that is 60 days after the date of enactment of the John D. Dingell, Jr. Conservation, Management, and Recreation Act, and unless the disclosure of such information is otherwise prohibited by law or a court order, the Secretary of the Treasury shall make available to the public on a website, as soon as practicable, but not later than 30 days after the date on which a payment under this section is tendered, the following information with regard to that payment:"],[1,"(1) The name of the specific agency or entity whose actions gave rise to the claim or judgment."],[1,"(2) The name of the plaintiff or claimant."],[1,"(3) The name of counsel for the plaintiff or claimant."],[1,"(4) The amount paid representing principal liability, and any amounts paid representing any ancillary liability, including attorney fees, costs, and interest."],[1,"(5) A brief description of the facts that gave rise to the claim."],[1,"(6) The name of the agency that submitted the claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/1304?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1304. Judgments, awards, and compromise settlements","tname":"Money and Finance","by":{"0":"16, 32","3":"29","6":"3, 4"}},{"t":"usc","label":"31 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/31/1341","subs":["(a)(1)(A)","(a)(1)","(a)","(a)(1)(B)"],"stext":{"head":"§1341. Limitations on expending and obligating amounts","paras":[[0,"(a)(1) Except as specified in this subchapter or any other provision of law, an officer or employee of the United States Government or of the District of Columbia government may not—"],[1,"(A) make or authorize an expenditure or obligation exceeding an amount available in an appropriation or fund for the expenditure or obligation;"],[1,"(B) involve either government in a contract or obligation for the payment of money before an appropriation is made unless authorized by law;"],[1,"(C) make or authorize an expenditure or obligation of funds required to be sequestered under section 252 of the Balanced Budget and Emergency Deficit Control Act of 1985; or"],[1,"(D) involve either government in a contract or obligation for the payment of money required to be sequestered under section 252 of the Balanced Budget and Emergency Deficit Control Act of 1985."],[0,"(2) This subsection does not apply to a corporation getting amounts to make loans (except paid in capital amounts) without legal liability of the United States Government."],[0,"(b) An article to be used by an executive department in the District of Columbia that could be bought out of an appropriation made to a regular contingent fund of the department may not be bought out of another amount available for obligation."],[0,"(c)(1) In this subsection—"],[1,"(A) the term \"covered lapse in appropriations\" means any lapse in appropriations that begins on or after December 22, 2018;"],[1,"(B) the term \"District of Columbia public employer\" means—"],[2,"(i) the District of Columbia Courts;"],[2,"(ii) the Public Defender Service for the District of Columbia; or"],[2,"(iii) the District of Columbia government;"],[1,"(C) the term \"employee\" includes an officer; and"],[1,"(D) the term \"excepted employee\" means an excepted employee or an employee performing emergency work, as such terms are defined by the Office of Personnel Management or the appropriate District of Columbia public employer, as applicable."],[0,"(2) Each employee of the United States Government or of a District of Columbia public employer furloughed as a result of a covered lapse in appropriations shall be paid for the period of the lapse in appropriations, and each excepted employee who is required to perform work during a covered lapse in appropriations shall be paid for such work, at the employee's standard rate of pay, at the earliest date possible after the lapse in appropriations ends, regardless of scheduled pay dates, and subject to the enactment of appropriations Acts ending the lapse."],[0,"(3) During a covered lapse in appropriations, each excepted employee who is required to perform work shall be entitled to use leave under chapter 63 of title 5, or any other applicable law governing the use of leave by the excepted employee, for which compensation shall be paid at the earliest date possible after the lapse in appropriations ends, regardless of scheduled pay dates."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/1341?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1341. Limitations on expending and obligating amounts","tname":"Money and Finance","by":{"0":"33","3":"9, 9, 9","4":"9, 9, 3, 7","5":"12","6":"14, 16"}},{"t":"usc","label":"42 U.S.C. § 280k","url":"https://www.law.cornell.edu/uscode/text/42/280k","subs":["(a)"],"stext":{"head":"§280k. Oral healthcare prevention education campaign","paras":[[0,"(a) Establishment of Oral Health Education Campaign"],[0,"The Secretary, acting through the Director of the Centers for Disease Control and Prevention and in consultation with professional oral health organizations, shall, subject to the availability of appropriations, establish a 5-year national, public education campaign (referred to in this section as the \"campaign\") that is focused on oral health education, including prevention of oral disease such as early childhood and other caries, periodontal disease, and oral cancer."],[0,"(b) Requirements"],[0,"In establishing the campaign under subsection (a), the Secretary shall—"],[1,"(1) ensure that activities are targeted towards specific populations such as children, pregnant women, parents, the elderly, individuals with disabilities, and ethnic and racial minority populations, including Indians, Alaska Natives and Native Hawaiians (as defined in section 1603(c) 1 of title 25) in a culturally and linguistically appropriate manner; and"],[1,"(2) utilize science-based strategies to convey oral health prevention messages that include, but are not limited to, community water fluoridation and dental sealants."],[0,"(c) Action for dental health program"],[0,"(1) In general"],[1,"The Secretary, in consultation with the Director of the Centers for Disease Control and Prevention and the Administrator of the Health Resources and Services Administration, may award grants, contracts, or cooperative agreements to eligible entities to collaborate with State or local public health officials, tribal health officials, oral health professional organizations, and others, as appropriate, to develop and implement initiatives to improve oral health, including activities to prevent dental disease and reduce barriers to the provision of dental services, including—"],[2,"(A) through community-wide dental disease prevention programs; and"],[2,"(B) by increasing public awareness and education related to oral health and dental disease prevention."],[0,"(2) Eligible entities"],[1,"To be eligible to receive a grant, contract, or cooperative agreement under this subsection, an entity shall be—"],[2,"(A) a dental association;"],[2,"(B) a State or tribal health department or State or tribal oral health program;"],[2,"(C) an accredited dental education, dental hygiene, or postdoctoral dental education program; or"],[2,"(D) a non-profit community-based organization that partners with public and private non-profit entities, such as an academic institution, to facilitate the provision of dental services to underserved populations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/280k?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§280k. Oral healthcare prevention education campaign","tname":"The Public Health and Welfare","by":{"0":"28","1":"6","4":"13","6":"5, 4"}},{"t":"usc","label":"42 U.S.C. § 293k-2","url":"https://www.law.cornell.edu/uscode/text/42/293k-2","subs":["(e)"],"stext":{"head":"§293k–2. Training in general, pediatric, and public health dentistry","paras":[[0,"(a) Support and development of dental training programs"],[0,"(1) In general"],[1,"The Secretary may make grants to, or enter into contracts with, a school of dentistry, public or nonprofit private hospital, or a public or private nonprofit entity which the Secretary has determined is capable of carrying out such grant or contract—"],[2,"(A) to plan, develop, and operate, or participate in, an approved professional training program in the field of general dentistry, pediatric dentistry, or public health dentistry for dental students, residents, practicing dentists, dental hygienists, or other approved primary care dental trainees, that emphasizes training for general, pediatric, or public health dentistry;"],[2,"(B) to provide financial assistance to dental students, residents, practicing dentists, and dental hygiene students who are in need thereof, who are participants in any such program, and who plan to work in the practice of general, pediatric, public heath dentistry, or dental hygiene;"],[2,"(C) to plan, develop, and operate a program for the training of oral health care providers who plan to teach in general, pediatric, public health dentistry, or dental hygiene;"],[2,"(D) to provide financial assistance in the form of traineeships and fellowships to dentists who plan to teach or are teaching in general, pediatric, or public health dentistry;"],[2,"(E) to meet the costs of projects to establish, maintain, or improve dental faculty development programs in primary care (which may be departments, divisions or other units);"],[2,"(F) to meet the costs of projects to establish, maintain, or improve predoctoral and postdoctoral training in primary care programs;"],[2,"(G) to create a loan repayment program for faculty in dental programs; and"],[2,"(H) to provide technical assistance to pediatric training programs in developing and implementing instruction regarding the oral health status, dental care needs, and risk-based clinical disease management of all pediatric populations with an emphasis on underserved children."],[0,"(2) Faculty loan repayment"],[0,"(A) In general"],[2,"A grant or contract under subsection (a)(1)(G) may be awarded to a program of general, pediatric, or public health dentistry described in such subsection to plan, develop, and operate a loan repayment program under which—"],[3,"(i) individuals agree to serve full-time as faculty members; and"],[3,"(ii) the program of general, pediatric or public health dentistry agrees to pay the principal and interest on the outstanding student loans of the individuals."],[0,"(B) Manner of payments"],[2,"With respect to the payments described in subparagraph (A)(ii), upon completion by an individual of each of the first, second, third, fourth, and fifth years of service, the program shall pay an amount equal to 10, 15, 20, 25, and 30 percent, respectively, of the individual's student loan balance as calculated based on principal and interest owed at the initiation of the agreement."],[0,"(b) Eligible entity"],[0,"For purposes of this subsection, entities eligible for such grants or contracts in general, pediatric, or public health dentistry shall include entities that have programs in dental or dental hygiene schools, or approved residency or advanced education programs in the practice of general, pediatric, or public health dentistry. Eligible entities may partner with schools of public health to permit the education of dental students, residents, and dental hygiene students for a master's year in public health at a school of public health."],[0,"(c) Priorities in making awards"],[0,"With respect to training provided for under this section, the Secretary shall give priority in awarding grants or contracts to the following:"],[1,"(1) Qualified applicants that propose collaborative projects between departments of primary care medicine and departments of general, pediatric, or public health dentistry."],[1,"(2) Qualified applicants that have a record of training the greatest percentage of providers, or that have demonstrated significant improvements in the percentage of providers, who enter and remain in general, pediatric, or public health dentistry."],[1,"(3) Qualified applicants that have a record of training individuals who are from a rural or disadvantaged background, or from underrepresented minorities."],[1,"(4) Qualified applicants that establish formal relationships with Federally qualified health centers, rural health centers, or accredited teaching facilities and that conduct training of students, residents, fellows, or faculty at the center or facility."],[1,"(5) Qualified applicants that conduct teaching programs targeting vulnerable populations such as older adults, homeless individuals, victims of abuse or trauma, individuals with mental health or substance use disorders, individuals with disabilities, and individuals with HIV/AIDS, and in the risk-based clinical disease management of all populations."],[1,"(6) Qualified applicants that include educational activities in cultural competency and health literacy."],[1,"(7) Qualified applicants that have a high rate for placing graduates in practice settings that serve underserved areas or health disparity populations, or who achieve a significant increase in the rate of placing graduates in such settings."],[1,"(8) Qualified applicants that intend to establish a special populations oral health care education center or training program for the didactic and clinical education of dentists, dental health professionals, and dental hygienists who plan to teach oral health care for people with developmental disabilities, cognitive impairment, complex medical problems, significant physical limitations, and vulnerable elderly."],[0,"(d) Application"],[0,"An eligible entity desiring a grant under this section shall submit to the Secretary an application at such time, in such manner, and containing such information as the Secretary may require."],[0,"(e) Duration of award"],[0,"The period during which payments are made to an entity from an award of a grant or contract under subsection (a) shall be 5 years. The provision of such payments shall be subject to annual approval by the Secretary and subject to the availability of appropriations for the fiscal year involved to make the payments."],[0,"(f) Authorizations of appropriations"],[0,"For the purpose of carrying out subsections (a) and (b), there is authorized to be appropriated $28,531,000 for each of fiscal years 2021 through 2025."],[0,"(g) Carryover funds"],[0,"An entity that receives an award under this section may carry over funds from 1 fiscal year to another without obtaining approval from the Secretary. In no case may any funds be carried over pursuant to the preceding sentence for more than 3 years."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/293k-2?type=usc&year=mostrecent&link-type=html"},"head":"§293k–2. Training in general, pediatric, and public health dentistry","tname":"The Public Health and Welfare","by":{"0":"28","1":"6","4":"13","6":"5"}},{"t":"usc","label":"42 U.S.C. § 1395w-115","url":"https://www.law.cornell.edu/uscode/text/42/1395w-115","subs":["(e)(3)(A)","(a)(2)","(e)(2)(B)"],"stext":{"head":"§1395w–115. Subsidies for part D eligible individuals for qualified prescription drug coverage","paras":[[0,"(a) Subsidy payment"],[0,"In order to reduce premium levels applicable to qualified prescription drug coverage for part D eligible individuals consistent with an overall subsidy level of 74.5 percent (or, for each of 2024 through 2029, the percent applicable as a result of the application of section 1395w–113(a)(8) of this title, or, for 2030 and each subsequent year, 100 percent minus the percent specified under section 1395w–113(a)(9) of this title) for basic prescription drug coverage, to reduce adverse selection among prescription drug plans and MA–PD plans, and to promote the participation of PDP sponsors under this part and MA organizations under part C, the Secretary shall provide for payment to a PDP sponsor that offers a prescription drug plan and an MA organization that offers an MA–PD plan of the following subsidies in accordance with this section:"],[0,"(1) Direct subsidy"],[1,"A direct subsidy for each part D eligible individual enrolled in a prescription drug plan or MA–PD plan for a month equal to—"],[2,"(A) the amount of the plan's standardized bid amount (as defined in section 1395w–113(a)(5) of this title), adjusted under subsection (c)(1), reduced by"],[2,"(B) the base beneficiary premium (as computed under paragraph (2) or (8) of section 1395w–113(a) of this title (as applicable) and as adjusted under paragraph (1)(B) of such section)."],[0,"(2) Subsidy through reinsurance"],[1,"The reinsurance payment amount (as defined in subsection (b))."],[0,"This section constitutes budget authority in advance of appropriations Acts and represents the obligation of the Secretary to provide for the payment of amounts provided under this section."],[0,"(b) Reinsurance payment amount"],[0,"(1) In general"],[1,"The reinsurance payment amount under this subsection for a part D eligible individual enrolled in a prescription drug plan or MA–PD plan for a coverage year is an amount equal to—"],[2,"(A) for a year preceding 2025, 80 percent of the allowable reinsurance costs (as specified in paragraph (2)) attributable to that portion of gross covered prescription drug costs as specified in paragraph (3) incurred in the coverage year after such individual has incurred costs that exceed the annual out-of-pocket threshold specified in section 1395w–102(b)(4)(B) of this title; and"],[2,"(B) for 2025 and each subsequent year, the sum of—"],[3,"(i) with respect to applicable drugs (as defined in section 1395w–114c(g)(2) of this title), an amount equal to 20 percent of such allowable reinsurance costs attributable to that portion of gross covered prescription drug costs as specified in paragraph (3) incurred in the coverage year after such individual has incurred costs that exceed the annual out-of-pocket threshold specified in section 1395w–102(b)(4)(B) of this title; and"],[3,"(ii) with respect to covered part D drugs that are not applicable drugs (as so defined), an amount equal to 40 percent of such allowable reinsurance costs attributable to that portion of gross covered prescription drug costs as specified in paragraph (3) incurred in the coverage year after such individual has incurred costs that exceed the annual out-of-pocket threshold specified in section 1395w–102(b)(4)(B) of this title."],[0,"(2) Allowable reinsurance costs"],[0,"(A) In general"],[2,"Subject to subparagraph (B), for purposes of this section, the term \"allowable reinsurance costs\" means, with respect to gross covered prescription drug costs under a prescription drug plan offered by a PDP sponsor or an MA–PD plan offered by an MA organization, the part of such costs that are actually paid (net of discounts, chargebacks, and average percentage rebates) by the sponsor or organization or by (or on behalf of) an enrollee under the plan, but in no case more than the part of such costs that would have been paid under the plan if the prescription drug coverage under the plan were basic prescription drug coverage, or, in the case of a plan providing supplemental prescription drug coverage, if such coverage were standard prescription drug coverage."],[0,"(B) Inclusion of manufacturer discounts on applicable drugs"],[2,"For purposes of applying subparagraph (A), the term \"allowable reinsurance costs\" shall include the portion of the negotiated price (as defined in section 1395w–114c(g)(6) of this title) of an applicable drug (as defined in section 1395w–114c(g)(2) of this title) that was paid by a manufacturer under the manufacturer discount program under section 1395w–114c of this title."],[0,"(3) Gross covered prescription drug costs"],[1,"Subject to paragraph (2)(B), for purposes of this section, the term \"gross covered prescription drug costs\" means, with respect to a part D eligible individual enrolled in a prescription drug plan or MA–PD plan during a coverage year, the costs incurred under the plan, not including administrative costs, but including costs directly related to the dispensing of covered part D drugs during the year and costs relating to the deductible. Such costs shall be determined whether they are paid by the individual or under the plan (or, with respect to 2025 and subsequent years, in the case of an applicable drug, as defined in section 1395w–114c(g)(2) of this title, by a manufacturer), regardless of whether the coverage under the plan exceeds basic prescription drug coverage."],[0,"(4) Coverage year defined"],[1,"For purposes of this section, the term \"coverage year\" means a calendar year in which covered part D drugs are dispensed if the claim for such drugs (and payment on such claim) is made not later than such period after the end of such year as the Secretary specifies."],[0,"(c) Adjustments relating to bids"],[0,"(1) Health status risk adjustment"],[0,"(A) Establishment of risk adjustors"],[2,"The Secretary shall establish an appropriate methodology for adjusting the standardized bid amount under subsection (a)(1)(A) to take into account variation in costs for basic prescription drug coverage among prescription drug plans and MA–PD plans based on the differences in actuarial risk of different enrollees being served. Any such risk adjustment shall be designed in a manner so as not to result in a change in the aggregate amounts payable to such plans under subsection (a)(1) and through that portion of the monthly beneficiary prescription drug premiums described in subsection (a)(1)(B) and MA monthly prescription drug beneficiary premiums."],[0,"(B) Considerations"],[2,"In establishing the methodology under subparagraph (A), the Secretary may take into account the similar methodologies used under section 1395w–23(a)(3) of this title to adjust payments to MA organizations for benefits under the original medicare fee-for-service program option."],[0,"(C) Data collection"],[2,"In order to carry out this paragraph, the Secretary shall require—"],[3,"(i) PDP sponsors to submit data regarding drug claims that can be linked at the individual level to part A and part B data and such other information as the Secretary determines necessary; and"],[3,"(ii) MA organizations that offer MA–PD plans to submit data regarding drug claims that can be linked at the individual level to other data that such organizations are required to submit to the Secretary and such other information as the Secretary determines necessary."],[0,"(D) Publication"],[2,"At the time of publication of risk adjustment factors under section 1395w–23(b)(1)(B)(i)(II) of this title, the Secretary shall publish the risk adjusters established under this paragraph for the succeeding year."],[0,"(2) Geographic adjustment"],[0,"(A) In general"],[2,"Subject to subparagraph (B), for purposes of section 1395w–113(a)(1)(B)(iii) of this title, the Secretary shall establish an appropriate methodology for adjusting the national average monthly bid amount (computed under section 1395w–113(a)(4) of this title) to take into account differences in prices for covered part D drugs among PDP regions."],[0,"(B) De minimis rule"],[2,"If the Secretary determines that the price variations described in subparagraph (A) among PDP regions are de minimis, the Secretary shall not provide for adjustment under this paragraph."],[0,"(C) Budget neutral adjustment"],[2,"Any adjustment under this paragraph shall be applied in a manner so as to not result in a change in the aggregate payments made under this part that would have been made if the Secretary had not applied such adjustment."],[0,"(d) Payment methods"],[0,"(1) In general"],[1,"Payments under this section shall be based on such a method as the Secretary determines. The Secretary may establish a payment method by which interim payments of amounts under this section are made during a year based on the Secretary's best estimate of amounts that will be payable after obtaining all of the information."],[0,"(2) Requirement for provision of information"],[0,"(A) Requirement"],[2,"Payments under this section to a PDP sponsor or MA organization are conditioned upon the furnishing to the Secretary, in a form and manner specified by the Secretary, of such information as may be required to carry out this section."],[0,"(B) Restriction on use of information"],[2,"Information disclosed or obtained pursuant to subparagraph (A) may be used by officers, employees, and contractors of the Department of Health and Human Services only for the purposes of, and to the extent necessary in, carrying out this section."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395w-115?type=usc&year=mostrecent&link-type=html"},"head":"§1395w–115. Subsidies for part D eligible individuals for qualified prescription drug coverage","tname":"The Public Health and Welfare","by":{"0":"26","1":"7","2":"8","3":"31, 31","4":"13, 14","5":"17","6":"6"}},{"t":"usc","label":"42 U.S.C. § 1397m-1","url":"https://www.law.cornell.edu/uscode/text/42/1397m-1","subs":["(b)(2)(A)"],"stext":{"head":"§1397m–1. Adult protective services functions and grant programs","paras":[[0,"(a) Secretarial responsibilities"],[0,"(1) In general"],[1,"The Secretary shall ensure that the Department of Health and Human Services—"],[2,"(A) provides funding authorized by this part to State and local adult protective services offices that investigate reports of the abuse, neglect, and exploitation of elders;"],[2,"(B) collects and disseminates data annually relating to the abuse, exploitation, and neglect of elders in coordination with the Department of Justice;"],[2,"(C) develops and disseminates information on best practices regarding, and provides training on, carrying out adult protective services;"],[2,"(D) conducts research related to the provision of adult protective services; and"],[2,"(E) provides technical assistance to States and other entities that provide or fund the provision of adult protective services, including through grants made under subsections (b) and (c)."],[0,"(2) Authorization of appropriations"],[1,"There are authorized to be appropriated to carry out this subsection, $3,000,000 for fiscal year 2011 and $4,000,000 for each of fiscal years 2012 through 2014."],[0,"(b) Grants to enhance the provision of adult protective services"],[0,"(1) Establishment"],[1,"There is established an adult protective services grant program under which the Secretary shall annually award grants to States in the amounts calculated under paragraph (2) for the purposes of enhancing adult protective services provided by States and local units of government."],[0,"(2) Amount of payment"],[0,"(A) In general"],[2,"Subject to the availability of appropriations and subparagraphs (B) and (C), the amount paid to a State for a fiscal year under the program under this subsection shall equal the amount appropriated for that year to carry out this subsection multiplied by the percentage of the total number of elders who reside in the United States who reside in that State."],[0,"(B) Guaranteed minimum payment amount"],[0,"(i) 50 States"],[3,"Subject to clause (ii), if the amount determined under subparagraph (A) for a State for a fiscal year is less than 0.75 percent of the amount appropriated for such year, the Secretary shall increase such determined amount so that the total amount paid under this subsection to the State for the year is equal to 0.75 percent of the amount so appropriated."],[0,"(ii) Territories"],[3,"In the case of a State other than 1 of the 50 States, clause (i) shall be applied as if each reference to \"0.75\" were a reference to \"0.1\"."],[0,"(C) Pro rata reductions"],[2,"The Secretary shall make such pro rata reductions to the amounts described in subparagraph (A) as are necessary to comply with the requirements of subparagraph (B)."],[0,"(3) Authorized activities"],[0,"(A) Adult protective services"],[2,"Funds made available pursuant to this subsection may only be used by States and local units of government to provide adult protective services and may not be used for any other purpose."],[0,"(B) Use by agency"],[2,"Each State receiving funds pursuant to this subsection shall provide such funds to the agency or unit of State government having legal responsibility for providing adult protective services within the State."],[0,"(C) Supplement not supplant"],[2,"Each State or local unit of government shall use funds made available pursuant to this subsection to supplement and not supplant other Federal, State, and local public funds expended to provide adult protective services in the State."],[0,"(4) State reports"],[1,"Each State receiving funds under this subsection shall submit to the Secretary, at such time and in such manner as the Secretary may require, a report on the number of elders served by the grants awarded under this subsection."],[0,"(5) Authorization of appropriations"],[1,"There are authorized to be appropriated to carry out this subsection, $100,000,000 for each of fiscal years 2011 through 2014."],[0,"(c) State demonstration programs"],[0,"(1) Establishment"],[1,"The Secretary shall award grants to States (and, in the case of demonstration programs described in paragraph (2)(E), to the highest courts of States) for the purposes of conducting demonstration programs in accordance with paragraph (2)."],[0,"(2) Demonstration programs"],[1,"Funds made available pursuant to this subsection may be used by States and local units of government (and the highest courts of States, in the case of demonstration programs described in subparagraph (E)) to conduct demonstration programs that test—"],[2,"(A) training modules developed for the purpose of detecting or preventing elder abuse;"],[2,"(B) methods to detect or prevent financial exploitation of elders;"],[2,"(C) methods to detect elder abuse;"],[2,"(D) whether training on elder abuse forensics enhances the detection of elder abuse by employees of the State or local unit of government;"],[2,"(E) subject to paragraph (3), programs to assess the fairness, effectiveness, timeliness, safety, integrity, and accessibility of adult guardianship and conservatorship proceedings, including the appointment and the monitoring of the performance of court-appointed guardians and conservators, and to implement changes deemed necessary as a result of the assessments such as mandating background checks for all potential guardians and conservators, and implementing systems to enable the annual accountings and other required conservatorship and guardianship filings to be completed, filed, and reviewed electronically in order to simplify the filing process for conservators and guardians and better enable courts to identify discrepancies and detect fraud and the exploitation of protected persons; or"],[2,"(F) other matters relating to the detection or prevention of elder abuse."],[0,"(3) Requirements for court-appointed guardianship oversight demonstration programs"],[0,"(A) Award of grants"],[2,"In awarding grants to the highest courts of States for demonstration programs described in paragraph (2)(E), the Secretary shall consider the recommendations of the Attorney General and the State Justice Institute, as established by section 10702 of this title."],[0,"(B) Collaboration"],[2,"The highest court of a State awarded a grant to conduct a demonstration program described in paragraph (2)(E) shall collaborate with the State Unit on Aging for the State and the Adult Protective Services agency for the State in conducting the demonstration program."],[0,"(4) Application"],[1,"To be eligible to receive a grant under this subsection, a State (and, in the case of demonstration programs described in paragraph (2)(E), the highest court of a State) shall submit an application to the Secretary at such time, in such manner, and containing such information as the Secretary may require."],[0,"(5) State reports"],[1,"Each State (or, in the case of demonstration programs described in paragraph (2)(E), the highest court of a State) that receives funds under this subsection shall submit to the Secretary a report at such time, in such manner, and containing such information as the Secretary may require on the results of the demonstration program conducted by the State (or, in the case of demonstration programs described in paragraph (2)(E), the highest court of a State) using funds made available under this subsection."],[0,"(6) Authorization of appropriations"],[1,"There are authorized to be appropriated to carry out this subsection, $25,000,000 for each of fiscal years 2011 through 2014."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1397m-1?type=usc&year=mostrecent&link-type=html"},"head":"§1397m–1. Adult protective services functions and grant programs","tname":"The Public Health and Welfare","by":{"0":"28","1":"6","4":"13","6":"5"}},{"t":"usc","label":"42 U.S.C. § 18042","url":"https://www.law.cornell.edu/uscode/text/42/18042","subs":["(g)"],"by":{"0":"8","3":"6, 8, 15, 23"}},{"t":"usc","label":"42 U.S.C. § 18062","url":"https://www.law.cornell.edu/uscode/text/42/18062","subs":["(a)","(b)(1)","(b)(2)"],"stext":{"head":"§18062. Establishment of risk corridors for plans in individual and small group markets","paras":[[0,"(a) In general"],[0,"The Secretary shall establish and administer a program of risk corridors for calendar years 2014, 2015, and 2016 under which a qualified health plan offered in the individual or small group market shall participate in a payment adjustment system based on the ratio of the allowable costs of the plan to the plan's aggregate premiums. Such program shall be based on the program for regional participating provider organizations under part D of title XVIII of the Social Security Act [42 U.S.C. 1395w–101 et seq.]."],[0,"(b) Payment methodology"],[0,"(1) Payments out"],[1,"The Secretary shall provide under the program established under subsection (a) that if—"],[2,"(A) a participating plan's allowable costs for any plan year are more than 103 percent but not more than 108 percent of the target amount, the Secretary shall pay to the plan an amount equal to 50 percent of the target amount in excess of 103 percent of the target amount; and"],[2,"(B) a participating plan's allowable costs for any plan year are more than 108 percent of the target amount, the Secretary shall pay to the plan an amount equal to the sum of 2.5 percent of the target amount plus 80 percent of allowable costs in excess of 108 percent of the target amount."],[0,"(2) Payments in"],[1,"The Secretary shall provide under the program established under subsection (a) that if—"],[2,"(A) a participating plan's allowable costs for any plan year are less than 97 percent but not less than 92 percent of the target amount, the plan shall pay to the Secretary an amount equal to 50 percent of the excess of 97 percent of the target amount over the allowable costs; and"],[2,"(B) a participating plan's allowable costs for any plan year are less than 92 percent of the target amount, the plan shall pay to the Secretary an amount equal to the sum of 2.5 percent of the target amount plus 80 percent of the excess of 92 percent of the target amount over the allowable costs."],[0,"(c) Definitions"],[0,"In this section:"],[0,"(1) Allowable costs"],[0,"(A) In general"],[2,"The amount of allowable costs of a plan for any year is an amount equal to the total costs (other than administrative costs) of the plan in providing benefits covered by the plan."],[0,"(B) Reduction for risk adjustment and reinsurance payments"],[2,"Allowable costs shall 1 reduced by any risk adjustment and reinsurance payments received under section 2 18061 and 18063 of this title."],[0,"(2) Target amount"],[1,"The target amount of a plan for any year is an amount equal to the total premiums (including any premium subsidies under any governmental program), reduced by the administrative costs of the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/18062?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§18062. Establishment of risk corridors for plans in individual and small group markets","tname":"The Public Health and Welfare","by":{"0":"passim","1":"passim","2":"5, 6, 8, 34","3":"passim, 6, 8, 15, 23, 6, 8, 15, 23, 7, 7","4":"passim","6":"passim, 4, 4, 4"}},{"t":"law","label":"Pub. L. No. 113-235","url":"https://www.govinfo.gov/link/plaw/113/public/235","by":{"0":"14, 35, 51","1":"24, 25","2":"14, 30","5":"4"}},{"t":"law","label":"Pub. L. No. 114-113","url":"https://www.govinfo.gov/link/plaw/114/public/113","by":{"0":"14, 51","1":"25","2":"14, 30","3":"10","5":"4"}},{"t":"law","label":"Pub. L. No. 115-31","url":"https://www.govinfo.gov/link/plaw/115/public/31","by":{"0":"14","2":"14, 30","3":"10","5":"4"}},{"t":"law","label":"Pub. L. No. 115-141","url":"https://www.govinfo.gov/link/plaw/115/public/141","by":{"0":"15","2":"15"}},{"t":"reg","label":"45 C.F.R. § 147.106","url":"https://www.ecfr.gov/current/title-45/section-147.106","subs":["(b)","(d)"],"by":{"0":"9, 9"}},{"t":"reg","label":"Federal Register, 77 Fed. Reg. 17,220","url":"https://www.govinfo.gov/link/fr/77/17220","by":{"0":"5","2":"7"}},{"t":"reg","label":"78 Fed. Reg. 15,410","url":"https://www.govinfo.gov/link/fr/78/15410","by":{"0":"11","1":"7","2":"8, 37","5":"9"}},{"t":"reg","label":"79 Fed. Reg. 13,744","url":"https://www.govinfo.gov/link/fr/79/13744","by":{"0":"11"}},{"t":"reg","label":"79 Fed. Reg. 30,240","url":"https://www.govinfo.gov/link/fr/79/30240","by":{"0":"12","2":"14"}},{"t":"reg","label":"80 Fed. Reg. 10,750","url":"https://www.govinfo.gov/link/fr/80/10750","by":{"0":"12","1":"12","2":"16","4":"10"}},{"t":"case","label":"Andrus v. Sierra Club","cite":"442 U.S. 347","y":1979,"id":"1978/78-625","sc":1,"sum":"Section 102 (2) (C) does not require federal agencies to prepare EIS's to accompany appropriation requests.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23","3":"21"}},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"sum":"The Court found that only tribes under federal jurisdiction at the time of the Indian Reorganization Act of 1934 are subject to taking by the federal government.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Carter v. United States","cite":"530 U.S. 255","y":2000,"id":"1999/99-5716","sc":1,"sum":"The Court held that federal bank larceny is not a \"lesser included offense\" of federal bank robbery. The \"[p]etitioner is accordingly prohibited as a matter of law from obtaining a lesser included offense instruction,\" wrote Justice Thomas for the Court.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Cherokee Nation of Oklahoma v. Leavitt","cite":"543 U.S. 631","y":2005,"id":"2004/02-1472","sc":1,"op":1,"ar":1,"sum":"Rejecting the Government's argument that it is legally bound by its contractual promise to pay “if, and only if, Congress appropriated suffcient funds”.","sumSrc":"opinion","by":{"1":"28, 36","3":"37, 56","5":"10","6":"passim"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Christensen v. Harris County","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"sum":"The Court held 6-3 that \"[n]othing in the FLSA or its implementing regulations prohibits a public employer from compelling the use of compensatory time.\" Justice Thomas wrote for the Court that, \"under the FLSA, an employer is free to require an employee to take time off work, and an employer is also free to use the money it would have paid in wages to cash out accrued compensatory time.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Claridge Apartments Co. v. Comm’r of Internal Revenue","cite":"323 U.S. 141","y":1944,"id":"scdb/1944-011","sc":1,"sum":"1. Whether, by virtue of § 276c (3) of the BankruptcyAct, § 270 was applicable to a proceeding under § 77B in which a final decree had been entered prior to the effective date of the Chandler, Act is a question of law in respect of which the doctrine of Dobson v. Commissioner,320 U. S. 489, is inapplicable and the determination of the Tax Court is not final. P..145., 2. Section 270 of the Bankruptcy Act, as amended, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"De Niz Robles v. Lynch","cite":"803 F.3d 1165","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/803/1165/","by":{"1":"43"}},{"t":"case","label":"Dowling v. U.S. Dep’t of Health and Human Servs.","cite":"325 F. Supp. 3d 884","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/325/884/","by":{"1":"43"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"22, 26, 35","2":"28, 33, 54","5":"3"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"1":"35","2":"34"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"King v. Burwell","cite":"135 S. Ct. 2480","y":2015,"id":"2014/14-114","sc":1,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"1":"48","3":"4, 5, 28"}},{"t":"case","label":"Land of Lincoln Mut. Health Ins. Co. v. United States","cite":"129 Fed. Cl. 81","y":2016,"url":"https://www.courtlistener.com/c/Fed.%20Cl./129/81/","op":1,"sum":"Describing imminent cancellation of insurance to 50,000 customers on account of government’s failure to make $74 million in risk corridors payments.","sumSrc":"brief:2","by":{"1":"1","2":"59","5":"11"}},{"t":"case","label":"Land of Lincoln Mut. Health Ins. Co. v. United States","cite":"892 F.3d 1184","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/892/1184/","op":5,"by":{"1":"1"}},{"t":"case","label":"Lynch v. United States","cite":"292 U.S. 571","y":1934,"id":"scdb/1933-150","sc":1,"sum":"1. Policies of yearly renewable term insurance issued under the War Risk Insurance Act, are not gratuities but are contracts of the United States.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"52","2":"53"}},{"t":"case","label":"Metroil, Inc. v. ExxonMobil Oil Corp.","cite":"672 F.3d 1108","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/672/1108/","by":{"1":"43"}},{"t":"case","label":"Mobil Oil Expl. & Producing Serv., Inc. v. United States","cite":"530 U.S. 604","y":2000,"id":"1999/99-244","sc":1,"sum":"The Court held that the Federal Government broke its promise, repudiated the contracts, and must give the companies their money back. \"We find that the oil companies gave the United States $158 million in return for a contractual promise to follow the terms of pre-existing statutes and regulations.","sumSrc":"Oyez","by":{"1":"52","2":"52, 53"}},{"t":"case","label":"Nat’l R.R. Passenger Corp. v. Atchison Topeka & Santa Fe Ry. Co.","cite":"470 U.S. 451","y":1985,"id":"1984/83-1492","sc":1,"sum":"The Rail Passenger Service Act of 1970 (Act or RPSA) was enacted in an attempt to revive the failing intercity passenger train industry. For this purpose the Act established the National Railroad Passenger Corporation (Amtrak), a private, for-profit corporation, authorized to operate, or contract with private railroads for the operation of, intercity rail passenger service. Most private railroads offering such …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"51","2":"51","3":"17, 35, 36, 53","5":"9"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"37","6":"23"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Robertson v. Seattle Audubon Soc.","cite":"503 U.S. 429","y":1992,"id":"1991/90-1596","sc":1,"op":1,"sum":"The Supreme Court held that §318 did not violate Article III because it made changes to the law by replacing the legal standards of the five challenged statutes. It did not make any findings of law or fact, or compel any results in the pending cases. The explicit reference to the cases only served to identify the statutes underlying those cases.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"St. Martin Evangelical Lutheran Church v. South Dakota","cite":"451 U.S. 772","y":1981,"id":"1980/80-120","sc":1,"op":1,"sum":"Petitioners are exempt from unemployment compensation taxes under § 3309 (b) (1) (A).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21, 45"}},{"t":"case","label":"Union Pac. R. Co. v. Laramie Stock Yards Co.","cite":"231 U.S. 190","y":1913,"id":"scdb/1913-023","sc":1,"sum":"The first rule of construction of statutes is that legislation is addressed to the future and not to the past. This rule is-one of obvious justice.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"United States v. Larionoff","cite":"431 U.S. 864","y":1977,"id":"1976/76-413","sc":1,"ar":1,"sum":"Respondent enlisted members of the United States Navy and others sumlarly situated, who agreed to extend their enlistments at a time when a statute provided for a Variable Re-enlistment Bonus (VRB), m addition to the Regular Re-enlistment Bonus (RRB), for members of the Armed Forces whose ratings were classified as a \"critical military skill\" held entitled to VRB's determined according to the award level m effect at …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44, 45","6":"25"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"United States v. Northern Pacific Railway Co.","cite":"256 U.S. 51","y":1921,"id":"scdb/1920-129","sc":1,"sum":"1. The Northern Pacific Railroad Act of July.2, 1864, c. 217, 13 Stat. 365, and the Joint Resolution of May 31, 1870, 16 Stat. 378, embodied a proposal that, if the company would bring about the construction and operation of the railroad, desired for the advantage of the Government and the public, it should receive in return the land comprehended by the granting provisions of the legislation. P, 63.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"51","6":"26"}},{"t":"case","label":"United States v. Security Industrial Bank","cite":"459 U.S. 70","y":1982,"id":"1982/81-184","sc":1,"sum":"Section 522(f)(2) was not intended to be applied retrospectively to destroy pre-enactment property rights.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"United States v. United States Gypsum Co.","cite":"438 U.S. 422","y":1978,"id":"1977/76-1560","sc":1,"sum":"Several major gypsum board manufacturers and various of their officials were indicted for violations of § 1 of the Sherman Act by allegedly engaging in a price-fixing conspiracy. One of the types of actions allegedly taken in formulating and effectuating the conspiracy was interseller price verification, i. e., the practice of telephoning a competing manufacturer to determine the price being currently offered on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"United States v. Winstar Corp.","cite":"518 U.S. 839","y":1996,"id":"1995/95-865","sc":1,"ar":2,"sum":"In a 7-2 plurality opinion delivered Justice David H. Souter, the Court held that the terms assigning the risk of regulatory change to the Government are enforceable and that the Government is therefore liable in damages for breach, although Congress changed the relevant law, and thereby barred the Government from specifically honoring its agreements.","sumSrc":"Oyez","by":{"1":"49","2":"52, 53, 57, 58","6":"4, 25"}},{"t":"case","label":"Vartelas v. Holder","cite":"566 U.S. 257","y":2012,"id":"2011/10-1211","sc":1,"sum":"The Court held that 8 U.S.C. § 1101(a)(13)(C)(v) cannot be applied retroactively to a lawful permanent resident who pleads guilty to a crime prior to the effective date of the Illegal Immigration Reform and Immigrant Responsibility Act.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 1395w-4","url":"https://www.law.cornell.edu/uscode/text/42/1395w-4","by":{"1":"6"}},{"t":"usc","label":"42 U.S.C. § 18061","url":"https://www.law.cornell.edu/uscode/text/42/18061","stext":{"head":"§18061. Transitional reinsurance program for individual market in each State","paras":[[0,"(a) In general"],[0,"Each State shall, not later than January 1, 2014—"],[1,"(1) include in the Federal standards or State law or regulation the State adopts and has in effect under section 18041(b) of this title the provisions described in subsection (b); and"],[1,"(2) establish (or enter into a contract with) 1 or more applicable reinsurance entities to carry out the reinsurance program under this section."],[0,"(b) Model regulation"],[0,"(1) In general"],[1,"In establishing the Federal standards under section 18041(a) of this title, the Secretary, in consultation with the National Association of Insurance Commissioners (the \"NAIC\"), shall include provisions that enable States to establish and maintain a program under which—"],[2,"(A) health insurance issuers, and third party administrators on behalf of group health plans, are required to make payments to an applicable reinsurance entity for any plan year beginning in the 3-year period beginning January 1, 2014 (as specified in paragraph (3); 1 and"],[2,"(B) the applicable reinsurance entity collects payments under subparagraph (A) and uses amounts so collected to make reinsurance payments to health insurance issuers described in subparagraph (A) that cover high risk individuals in the individual market (excluding grandfathered health plans) for any plan year beginning in such 3-year period."],[0,"(2) High-risk individual; payment amounts"],[1,"The Secretary shall include the following in the provisions under paragraph (1):"],[0,"(A) Determination of high-risk individuals"],[2,"The method by which individuals will be identified as high risk individuals for purposes of the reinsurance program established under this section. Such method shall provide for identification of individuals as high-risk individuals on the basis of—"],[3,"(i) a list of at least 50 but not more than 100 medical conditions that are identified as high-risk conditions and that may be based on the identification of diagnostic and procedure codes that are indicative of individuals with pre-existing, high-risk conditions; or"],[3,"(ii) any other comparable objective method of identification recommended by the American Academy of Actuaries."],[0,"(B) Payment amount"],[2,"The formula for determining the amount of payments that will be paid to health insurance issuers described in paragraph (1)(B) that insure high-risk individuals. Such formula shall provide for the equitable allocation of available funds through reconciliation and may be designed—"],[3,"(i) to provide a schedule of payments that specifies the amount that will be paid for each of the conditions identified under subparagraph (A); or"],[3,"(ii) to use any other comparable method for determining payment amounts that is recommended by the American Academy of Actuaries and that encourages the use of care coordination and care management programs for high risk conditions."],[0,"(3) Determination of required contributions"],[0,"(A) In general"],[2,"The Secretary shall include in the provisions under paragraph (1) the method for determining the amount each health insurance issuer and group health plan described in paragraph (1)(A) contributing to the reinsurance program under this section is required to contribute under such paragraph for each plan year beginning in the 36-month period beginning January 1, 2014. The contribution amount for any plan year may be based on the percentage of revenue of each issuer and the total costs of providing benefits to enrollees in self-insured plans or on a specified amount per enrollee and may be required to be paid in advance or periodically throughout the plan year."],[0,"(B) Specific requirements"],[2,"The method under this paragraph shall be designed so that—"],[3,"(i) the contribution amount for each issuer proportionally reflects each issuer's fully insured commercial book of business for all major medical products and the total value of all fees charged by the issuer and the costs of coverage administered by the issuer as a third party administrator;"],[3,"(ii) the contribution amount can include an additional amount to fund the administrative expenses of the applicable reinsurance entity;"],[3,"(iii) the aggregate contribution amounts for all States shall, based on the best estimates of the NAIC and without regard to amounts described in clause (ii), equal $10,000,000,000 for plan years beginning in 2014, $6,000,000,000 for plan years beginning 2 2015, and $4,000,000,000 for plan years beginning in 2016; and"],[3,"(iv) in addition to the aggregate contribution amounts under clause (iii), each issuer's contribution amount for any calendar year under clause (iii) reflects its proportionate share of an additional $2,000,000,000 for 2014, an additional $2,000,000,000 for 2015, and an additional $1,000,000,000 for 2016."],[2,"Nothing in this subparagraph shall be construed to preclude a State from collecting additional amounts from issuers on a voluntary basis."],[0,"(4) Expenditure of funds"],[1,"The provisions under paragraph (1) shall provide that—"],[2,"(A) the contribution amounts collected for any calendar year may be allocated and used in any of the three calendar years for which amounts are collected based on the reinsurance needs of a particular period or to reflect experience in a prior period; and"],[2,"(B) amounts remaining unexpended as of December, 2016, may be used to make payments under any reinsurance program of a State in the individual market in effect in the 2-year period beginning on January 1, 2017."],[1,"Notwithstanding the preceding sentence, any contribution amounts described in paragraph (3)(B)(iv) shall be deposited into the general fund of the Treasury of the United States and may not be used for the program established under this section."],[0,"(c) Applicable reinsurance entity"],[0,"For purposes of this section—"],[0,"(1) In general"],[1,"The term \"applicable reinsurance entity\" means a not-for-profit organization—"],[2,"(A) the purpose of which is to help stabilize premiums for coverage in the individual market in a State during the first 3 years of operation of an Exchange for such markets within the State when the risk of adverse selection related to new rating rules and market changes is greatest; and"],[2,"(B) the duties of which shall be to carry out the reinsurance program under this section by coordinating the funding and operation of the risk-spreading mechanisms designed to implement the reinsurance program."],[0,"(2) State discretion"],[1,"A State may have more than 1 applicable reinsurance entity to carry out the reinsurance program under this section within the State and 2 or more States may enter into agreements to provide for an applicable reinsurance entity to carry out such program in all such States."],[0,"(3) Entities are tax-exempt"],[1,"An applicable reinsurance entity established under this section shall be exempt from taxation under chapter 1 of title 26. The preceding sentence shall not apply to the tax imposed by section 511 such 3 title (relating to tax on unrelated business taxable income of an exempt organization)."],[0,"(d) Coordination with State high-risk pools"],[0,"The State shall eliminate or modify any State high-risk pool to the extent necessary to carry out the reinsurance program established under this section. The State may coordinate the State high-risk pool with such program to the extent not inconsistent with the provisions of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/18061?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§18061. Transitional reinsurance program for individual market in each State","tname":"The Public Health and Welfare","by":{"1":"4, 7","3":"6, 5"}},{"t":"usc","label":"42 U.S.C. § 18063","url":"https://www.law.cornell.edu/uscode/text/42/18063","stext":{"head":"§18063. Risk adjustment","paras":[[0,"(a) In general"],[0,"(1) Low actuarial risk plans"],[1,"Using the criteria and methods developed under subsection (b), each State shall assess a charge on health plans and health insurance issuers (with respect to health insurance coverage) described in subsection (c) if the actuarial risk of the enrollees of such plans or coverage for a year is less than the average actuarial risk of all enrollees in all plans or coverage in such State for such year that are not self-insured group health plans (which are subject to the provisions of the Employee Retirement Income Security Act of 1974 [29 U.S.C. 1001 et seq.])."],[0,"(2) High actuarial risk plans"],[1,"Using the criteria and methods developed under subsection (b), each State shall provide a payment to health plans and health insurance issuers (with respect to health insurance coverage) described in subsection (c) if the actuarial risk of the enrollees of such plans or coverage for a year is greater than the average actuarial risk of all enrollees in all plans and coverage in such State for such year that are not self-insured group health plans (which are subject to the provisions of the Employee Retirement Income Security Act of 1974)."],[0,"(b) Criteria and methods"],[0,"The Secretary, in consultation with States, shall establish criteria and methods to be used in carrying out the risk adjustment activities under this section. The Secretary may utilize criteria and methods similar to the criteria and methods utilized under part C or D of title XVIII of the Social Security Act [42 U.S.C. 1395w–21 et seq., 1395w–101 et seq.]. Such criteria and methods shall be included in the standards and requirements the Secretary prescribes under section 18041 of this title."],[0,"(c) Scope"],[0,"A health plan or a health insurance issuer is described in this subsection if such health plan or health insurance issuer provides coverage in the individual or small group market within the State. This subsection shall not apply to a grandfathered health plan or the issuer of a grandfathered health plan with respect to that plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/18063?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§18063. Risk adjustment","tname":"The Public Health and Welfare","by":{"1":"4","3":"6"}},{"t":"usc","label":"42 U.S.C. § 300hh-31","url":"https://www.law.cornell.edu/uscode/text/42/300hh-31","by":{"1":"6","6":"5"}},{"t":"reg","label":"45 C.F.R. § 153.510","url":"https://www.ecfr.gov/current/title-45/section-153.510","by":{"1":"7"}},{"t":"reg","label":"77 Fed. Reg. 17,251","url":"https://www.govinfo.gov/link/fr/77/17251","by":{"1":"7"}},{"t":"reg","label":"78 Fed. Reg. 15,413","url":"https://www.govinfo.gov/link/fr/78/15413","by":{"1":"46-47"}},{"t":"reg","label":"78 Fed. Reg. 15,441","url":"https://www.govinfo.gov/link/fr/78/15441","by":{"1":"7"}},{"t":"reg","label":"78 Fed. Reg. 15,473","url":"https://www.govinfo.gov/link/fr/78/15473","by":{"1":"7"}},{"t":"reg","label":"79 Fed. Reg. 13,746","url":"https://www.govinfo.gov/link/fr/79/13746","by":{"1":"40"}},{"t":"reg","label":"79 Fed. Reg. 13,786","url":"https://www.govinfo.gov/link/fr/79/13786","by":{"1":"40"}},{"t":"reg","label":"79 Fed. Reg. 13,787","url":"https://www.govinfo.gov/link/fr/79/13787","by":{"1":"39"}},{"t":"reg","label":"79 Fed. Reg. 30,260","url":"https://www.govinfo.gov/link/fr/79/30260","by":{"1":"9","2":"14","6":"9"}},{"t":"reg","label":"80 Fed. Reg. 10,779","url":"https://www.govinfo.gov/link/fr/80/10779","by":{"1":"12"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"136 S. Ct. 1310","y":2016,"id":"2015/14-770","sc":1,"sum":"The Court decided that a statute effectively directing a particular result in a single pending case does not violate the separation of powers.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Belknap v. United States","cite":"150 U.S. 588","y":1893,"id":"scdb/1893-068","sc":1,"ar":1,"sum":"Ordinarily a court lias no power to grant a new trial at a term subsequent to tliat at which the original judgment was rendered.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"30, 39","3":"51","5":"15"}},{"t":"case","label":"Cook Cty. v. United States ex rel. Chandler","cite":"538 U.S. 119","y":2003,"id":"2002/01-1572","sc":1,"sum":"The Court held that the term \"person\" includes local governments. The Court noted that the County, as a recipient of federal funding, was clearly able to abuse federal spending and was thus subject to the FCA remedy that applied to prevent such abuse.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"E. Enters. v. Apfel","cite":"524 U.S. 498","y":1998,"id":"1997/97-42","sc":1,"sum":"Currently unknown.","sumSrc":"Oyez","by":{"2":"47, 48"}},{"t":"case","label":"Fourth Estate Pub. Benefit Corp. v. Wall-Street.com, LLC","cite":"139 S. Ct. 881","y":2019,"id":"2018/17-571","sc":1,"op":3,"sum":"Registration occurs, and a copyright claimant may commence an infringement suit, when the Copyright Office registers a copyright.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"37"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"2":"56"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"2":"33, 54"}},{"t":"case","label":"Murr v. Wisconsin","cite":"137 S. Ct. 1933","y":2017,"id":"2016/15-214","sc":1,"sum":"The Court determined that, in a regulatory takings case, two legally distinct but commonly owned contiguous parcels should be combined for takings analysis purposes.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"2":"55"}},{"t":"case","label":"Penn Cent. Transp. Co. v. City of N.Y.","cite":"438 U.S. 104","y":1978,"id":"1977/77-444","sc":1,"sum":"The Court held that the restrictions imposed did not prevent Penn Central from ever constructing above the terminal in the future. New York's objection was to the nature of the proposed construction and not to construction in general implemented to \"enhance\" the Terminal.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Schwegmann Bros. v. Calvert Distillers Corp.","cite":"341 U.S. 384","y":1951,"id":"scdb/1950-082","sc":1,"sum":"Respondents were not entitled by reason of the Miller-Tydings Act to enjoin petitioner from selling their products at less than the minimum prices fixed by their schedules.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"35"}},{"t":"case","label":"Shannon v. United States","cite":"512 U.S. 573","y":1994,"id":"1993/92-8346","sc":1,"sum":"The city's dedication requirements constitute an uncompensated taking of property.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36"}},{"t":"case","label":"United States v. Borden Co.","cite":"308 U.S. 188","y":1939,"id":"scdb/1939-008","sc":1,"op":1,"sum":"1. A judgment quashing a count upon the ground of duplicity is not appealable to this Courl under the Criminal Appeals Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"United States v. Bostwick","cite":"94 U.S. 53","y":1876,"id":"scdb/1876-108","sc":1,"sum":"Tbis was a suit by Tbomas R. Lovett, trustee of Mrs. Louisa Fletcher, against the United States, to recover the rent of and for damages to certain real estate and premises situated in the District of Columbia, and known as Kalorama.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"53"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"135 S. Ct. 1625","y":2015,"id":"2014/13-1074","sc":1,"op":1,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"United States v. R.L.C.","cite":"503 U.S. 291","y":1992,"id":"1991/90-1577","sc":1,"sum":"The judgment is affirmed. 915 F. 2d 320, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"35"}},{"t":"usc","label":"26 U.S.C. § 36B","url":"https://www.law.cornell.edu/uscode/text/26/36B","stext":{"head":"§36B. Refundable credit for coverage under a qualified health plan","paras":[[0,"(a) In general"],[0,"In the case of an applicable taxpayer, there shall be allowed as a credit against the tax imposed by this subtitle for any taxable year an amount equal to the premium assistance credit amount of the taxpayer for the taxable year."],[0,"(b) Premium assistance credit amount"],[0,"For purposes of this section—"],[0,"(1) In general"],[1,"The term \"premium assistance credit amount\" means, with respect to any taxable year, the sum of the premium assistance amounts determined under paragraph (2) with respect to all coverage months of the taxpayer occurring during the taxable year."],[0,"(2) Premium assistance amount"],[1,"The premium assistance amount determined under this subsection with respect to any coverage month is the amount equal to the lesser of—"],[2,"(A) the monthly premiums for such month for 1 or more qualified health plans offered in the individual market within a State which cover the taxpayer, the taxpayer's spouse, or any dependent (as defined in section 152) of the taxpayer and which were enrolled in through an Exchange established by the State under 1311 1 of the Patient Protection and Affordable Care Act, or"],[2,"(B) the excess (if any) of—"],[3,"(i) the adjusted monthly premium for such month for the applicable second lowest cost silver plan with respect to the taxpayer, over"],[3,"(ii) an amount equal to 1/12 of the product of the applicable percentage and the taxpayer's household income for the taxable year."],[0,"(3) Other terms and rules relating to premium assistance amounts"],[1,"For purposes of paragraph (2)—"],[0,"(A) Applicable percentage"],[0,"(i) In general"],[3,"Except as provided in clause (ii), the applicable percentage for any taxable year shall be the percentage such that the applicable percentage for any taxpayer whose household income is within an income tier specified in the following table shall increase, on a sliding scale in a linear manner, from the initial premium percentage to the final premium percentage specified in such table for such income tier:"],[0,"(ii) Indexing"],[0,"(I) In general"],[4,"Subject to subclause (II), in the case of taxable years beginning in any calendar year after 2014, the initial and final applicable percentages under clause (i) (as in effect for the preceding calendar year after application of this clause) shall be adjusted to reflect the excess of the rate of premium growth for the preceding calendar year over the rate of income growth for the preceding calendar year."],[0,"(II) Additional adjustment"],[4,"Except as provided in subclause (III), in the case of any calendar year after 2018, the percentages described in subclause (I) shall, in addition to the adjustment under subclause (I), be adjusted to reflect the excess (if any) of the rate of premium growth estimated under subclause (I) for the preceding calendar year over the rate of growth in the consumer price index for the preceding calendar year."],[0,"(III) Failsafe"],[4,"Subclause (II) shall apply for any calendar year only if the aggregate amount of premium tax credits under this section and cost-sharing reductions under section 1402 of the Patient Protection and Affordable Care Act for the preceding calendar year exceeds an amount equal to 0.504 percent of the gross domestic product for the preceding calendar year."],[0,"(iii) Temporary percentages for 2021 through 2025"],[3,"In the case of a taxable year beginning after December 31, 2020, and before January 1, 2026—"],[4,"(I) clause (ii) shall not apply for purposes of adjusting premium percentages under this subparagraph, and"],[4,"(II) the following table shall be applied in lieu of the table contained in clause (i):"],[0,"(B) Applicable second lowest cost silver plan"],[2,"The applicable second lowest cost silver plan with respect to any applicable taxpayer is the second lowest cost silver plan of the individual market in the rating area in which the taxpayer resides which—"],[3,"(i) is offered through the same Exchange through which the qualified health plans taken into account under paragraph (2)(A) were offered, and"],[3,"(ii) provides—"],[4,"(I) self-only coverage in the case of an applicable taxpayer—"],[5,"(aa) whose tax for the taxable year is determined under section 1(c) 2 (relating to unmarried individuals other than surviving spouses and heads of households) and who is not allowed a deduction under section 151 for the taxable year with respect to a dependent, or"],[5,"(bb) who is not described in item (aa) but who purchases only self-only coverage, and"],[4,"(II) family coverage in the case of any other applicable taxpayer."],[2,"If a taxpayer files a joint return and no credit is allowed under this section with respect to 1 of the spouses by reason of subsection (e), the taxpayer shall be treated as described in clause (ii)(I) unless a deduction is allowed under section 151 for the taxable year with respect to a dependent other than either spouse and subsection (e) does not apply to the dependent."],[0,"(C) Adjusted monthly premium"],[2,"The adjusted monthly premium for an applicable second lowest cost silver plan is the monthly premium which would have been charged (for the rating area with respect to which the premiums under paragraph (2)(A) were determined) for the plan if each individual covered under a qualified health plan taken into account under paragraph (2)(A) were covered by such silver plan and the premium was adjusted only for the age of each such individual in the manner allowed under section 2701 of the Public Health Service Act. In the case of a State participating in the wellness discount demonstration project under section 2705(d) of the Public Health Service Act, the adjusted monthly premium shall be determined without regard to any premium discount or rebate under such project."],[0,"(D) Additional benefits"],[2,"If—"],[3,"(i) a qualified health plan under section 1302(b)(5) of the Patient Protection and Affordable Care Act offers benefits in addition to the essential health benefits required to be provided by the plan, or"],[3,"(ii) a State requires a qualified health plan under section 1311(d)(3)(B) of such Act to cover benefits in addition to the essential health benefits required to be provided by the plan,"],[2,"the portion of the premium for the plan properly allocable (under rules prescribed by the Secretary of Health and Human Services) to such additional benefits shall not be taken into account in determining either the monthly premium or the adjusted monthly premium under paragraph (2)."],[0,"(E) Special rule for pediatric dental coverage"],[2,"For purposes of determining the amount of any monthly premium, if an individual enrolls in both a qualified health plan and a plan described in section 1311(d)(2)(B)(ii)(I) 2 of the Patient Protection and Affordable Care Act for any plan year, the portion of the premium for the plan described in such section that (under regulations prescribed by the Secretary) is properly allocable to pediatric dental benefits which are included in the essential health benefits required to be provided by a qualified health plan under section 1302(b)(1)(J) of such Act shall be treated as a premium payable for a qualified health plan."],[0,"(c) Definition and rules relating to applicable taxpayers, coverage months, and qualified health plan"],[0,"For purposes of this section—"],[0,"(1) Applicable taxpayer"],[0,"(A) In general"],[2,"The term \"applicable taxpayer\" means, with respect to any taxable year, a taxpayer whose household income for the taxable year equals or exceeds 100 percent but does not exceed 400 percent of an amount equal to the poverty line for a family of the size involved."],[0,"(B) Special rule for certain individuals lawfully present in the United States"],[2,"If—"],[3,"(i) a taxpayer has a household income which is not greater than 100 percent of an amount equal to the poverty line for a family of the size involved, and"],[3,"(ii) the taxpayer is an alien lawfully present in the United States, but is not eligible for the medicaid program under title XIX of the Social Security Act by reason of such alien status,"],[2,"the taxpayer shall, for purposes of the credit under this section, be treated as an applicable taxpayer with a household income which is equal to 100 percent of the poverty line for a family of the size involved."],[0,"(C) Married couples must file joint return"],[2,"If the taxpayer is married (within the meaning of section 7703) at the close of the taxable year, the taxpayer shall be treated as an applicable taxpayer only if the taxpayer and the taxpayer's spouse file a joint return for the taxable year."],[0,"(D) Denial of credit to dependents"],[2,"No credit shall be allowed under this section to any individual with respect to whom a deduction under section 151 is allowable to another taxpayer for a taxable year beginning in the calendar year in which such individual's taxable year begins."],[0,"(E) Temporary rule for 2021 through 2025"],[2,"In the case of a taxable year beginning after December 31, 2020, and before January 1, 2026, subparagraph (A) shall be applied without regard to \"but does not exceed 400 percent\"."],[0,"(2) Coverage month"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"coverage month\" means, with respect to an applicable taxpayer, any month if—"],[3,"(i) as of the first day of such month the taxpayer, the taxpayer's spouse, or any dependent of the taxpayer is covered by a qualified health plan described in subsection (b)(2)(A) that was enrolled in through an Exchange established by the State under section 1311 of the Patient Protection and Affordable Care Act, and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/36B?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§36B. Refundable credit for coverage under a qualified health plan","tname":"Internal Revenue Code","by":{"2":"4","3":"5, 55"}},{"t":"usc","label":"42 U.S.C. § 18031","url":"https://www.law.cornell.edu/uscode/text/42/18031","subs":["(a)(1)"],"stext":{"head":"§18031. Affordable choices of health benefit plans","paras":[[0,"(a) Assistance to States to establish American Health Benefit Exchanges"],[0,"(1) Planning and establishment grants"],[1,"There shall be appropriated to the Secretary, out of any moneys in the Treasury not otherwise appropriated, an amount necessary to enable the Secretary to make awards, not later than 1 year after March 23, 2010, to States in the amount specified in paragraph (2) for the uses described in paragraph (3)."],[0,"(2) Amount specified"],[1,"For each fiscal year, the Secretary shall determine the total amount that the Secretary will make available to each State for grants under this subsection."],[0,"(3) Use of funds"],[1,"A State shall use amounts awarded under this subsection for activities (including planning activities) related to establishing an American Health Benefit Exchange, as described in subsection (b)."],[0,"(4) Renewability of grant"],[0,"(A) In general"],[2,"Subject to subsection (d)(4), the Secretary may renew a grant awarded under paragraph (1) if the State recipient of such grant—"],[3,"(i) is making progress, as determined by the Secretary, toward—"],[4,"(I) establishing an Exchange; and"],[4,"(II) implementing the reforms described in subtitles A and C (and the amendments made by such subtitles); and"],[3,"(ii) is meeting such other benchmarks as the Secretary may establish."],[0,"(B) Limitation"],[2,"No grant shall be awarded under this subsection after January 1, 2015."],[0,"(5) Technical assistance to facilitate participation in SHOP Exchanges"],[1,"The Secretary shall provide technical assistance to States to facilitate the participation of qualified small businesses in such States in SHOP Exchanges."],[0,"(b) American Health Benefit Exchanges"],[0,"(1) In general"],[1,"Each State shall, not later than January 1, 2014, establish an American Health Benefit Exchange (referred to in this title 1 as an \"Exchange\") for the State that—"],[2,"(A) facilitates the purchase of qualified health plans;"],[2,"(B) provides for the establishment of a Small Business Health Options Program (in this title 1 referred to as a \"SHOP Exchange\") that is designed to assist qualified employers in the State who are small employers in facilitating the enrollment of their employees in qualified health plans offered in the small group market in the State; and"],[2,"(C) meets the requirements of subsection (d)."],[0,"(2) Merger of individual and SHOP Exchanges"],[1,"A State may elect to provide only one Exchange in the State for providing both Exchange and SHOP Exchange services to both qualified individuals and qualified small employers, but only if the Exchange has adequate resources to assist such individuals and employers."],[0,"(c) Responsibilities of the Secretary"],[0,"(1) In general"],[1,"The Secretary shall, by regulation, establish criteria for the certification of health plans as qualified health plans. Such criteria shall require that, to be certified, a plan shall, at a minimum—"],[2,"(A) meet marketing requirements, and not employ marketing practices or benefit designs that have the effect of discouraging the enrollment in such plan by individuals with significant health needs;"],[2,"(B) ensure a sufficient choice of providers (in a manner consistent with applicable network adequacy provisions under section 2702(c) of the Public Health Service Act [42 U.S.C. 300gg–1(c)]), and provide information to enrollees and prospective enrollees on the availability of in-network and out-of-network providers;"],[2,"(C) include within health insurance plan networks those essential community providers, where available, that serve predominately low-income, medically-underserved individuals, such as health care providers defined in section 340B(a)(4) of the Public Health Service Act [42 U.S.C. 256b(a)(4)] and providers described in section 1927(c)(1)(D)(i)(IV) of the Social Security Act [42 U.S.C. 1396r–8(c)(1)(D)(i)(IV)] as set forth by section 221 of Public Law 111–8, except that nothing in this subparagraph shall be construed to require any health plan to provide coverage for any specific medical procedure;"],[2,"(D)(i) be accredited with respect to local performance on clinical quality measures such as the Healthcare Effectiveness Data and Information Set, patient experience ratings on a standardized Consumer Assessment of Healthcare Providers and Systems survey, as well as consumer access, utilization management, quality assurance, provider credentialing, complaints and appeals, network adequacy and access, and patient information programs by any entity recognized by the Secretary for the accreditation of health insurance issuers or plans (so long as any such entity has transparent and rigorous methodological and scoring criteria); or"],[2,"(ii) receive such accreditation within a period established by an Exchange for such accreditation that is applicable to all qualified health plans;"],[2,"(E) implement a quality improvement strategy described in subsection (g)(1);"],[2,"(F) utilize a uniform enrollment form that qualified individuals and qualified employers may use (either electronically or on paper) in enrolling in qualified health plans offered through such Exchange, and that takes into account criteria that the National Association of Insurance Commissioners develops and submits to the Secretary;"],[2,"(G) utilize the standard format established for presenting health benefits plan options;"],[2,"(H) provide information to enrollees and prospective enrollees, and to each Exchange in which the plan is offered, on any quality measures for health plan performance endorsed under section 399JJ of the Public Health Service Act [42 U.S.C. 280j–2], as applicable; and"],[2,"(I) report to the Secretary at least annually and in such manner as the Secretary shall require, pediatric quality reporting measures consistent with the pediatric quality reporting measures established under section 1139A of the Social Security Act [42 U.S.C. 1320b–9a]."],[0,"(2) Rule of construction"],[1,"Nothing in paragraph (1)(C) shall be construed to require a qualified health plan to contract with a provider described in such paragraph if such provider refuses to accept the generally applicable payment rates of such plan."],[0,"(3) Rating system"],[1,"The Secretary shall develop a rating system that would rate qualified health plans offered through an Exchange in each benefits level on the basis of the relative quality and price. The Exchange shall include the quality rating in the information provided to individuals and employers through the Internet portal established under paragraph (4)."],[0,"(4) Enrollee satisfaction system"],[1,"The Secretary shall develop an enrollee satisfaction survey system that would evaluate the level of enrollee satisfaction with qualified health plans offered through an Exchange, for each such qualified health plan that had more than 500 enrollees in the previous year. The Exchange shall include enrollee satisfaction information in the information provided to individuals and employers through the Internet portal established under paragraph (5) in a manner that allows individuals to easily compare enrollee satisfaction levels between comparable plans."],[0,"(5) Internet portals"],[1,"The Secretary shall—"],[2,"(A) continue to operate, maintain, and update the Internet portal developed under section 18003(a) of this title and to assist States in developing and maintaining their own such portal; and"],[2,"(B) make available for use by Exchanges a model template for an Internet portal that may be used to direct qualified individuals and qualified employers to qualified health plans, to assist such individuals and employers in determining whether they are eligible to participate in an Exchange or eligible for a premium tax credit or cost-sharing reduction, and to present standardized information (including quality ratings) regarding qualified health plans offered through an Exchange to assist consumers in making easy health insurance choices."],[1,"Such template shall include, with respect to each qualified health plan offered through the Exchange in each rating area, access to the uniform outline of coverage the plan is required to provide under section 2716 1 of the Public Health Service Act and to a copy of the plan's written policy."],[0,"(6) Enrollment periods"],[1,"The Secretary shall require an Exchange to provide for—"],[2,"(A) an initial open enrollment, as determined by the Secretary (such determination to be made not later than July 1, 2012);"],[2,"(B) annual open enrollment periods, as determined by the Secretary for calendar years after the initial enrollment period;"],[2,"(C) special enrollment periods specified in section 9801 of title 26 and other special enrollment periods under circumstances similar to such periods under part D of title XVIII of the Social Security Act [42 U.S.C. 1395w–101 et seq.]; and"],[2,"(D) special monthly enrollment periods for Indians (as defined in section 1603 of title 25)."],[0,"(7) Reenrollment of certain individuals in qualified health plans in certain exchanges"],[0,"(A) In general"],[2,"In the case of an Exchange that the Secretary operates pursuant to section 18041(c)(1) of this title, the Secretary shall establish a process under which an individual described in subparagraph (B) is reenrolled for plan year 2021 in a qualified health plan offered through such Exchange. Such qualified health plan under which such individual is so reenrolled shall be—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/18031?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§18031. Affordable choices of health benefit plans","tname":"The Public Health and Welfare","by":{"2":"3","3":"6","6":"6, 4"}},{"t":"usc","label":"42 U.S.C. § 300gg-94","url":"https://www.law.cornell.edu/uscode/text/42/300gg-94","by":{"2":"11"}},{"t":"law","label":"Pub. L. No. 111-148","url":"https://www.govinfo.gov/link/plaw/111/public/148","by":{"2":"10"}},{"t":"law","label":"Pub. L. No. 115-245","url":"https://www.govinfo.gov/link/plaw/115/public/245","by":{"2":"15"}},{"t":"reg","label":"45 C.F.R. pt. 153","url":"https://www.ecfr.gov/current/title-45/part-153","by":{"2":"6, 7"}},{"t":"reg","label":"45 C.F.R. § 154.200","url":"https://www.ecfr.gov/current/title-45/section-154.200","by":{"2":"11"}},{"t":"reg","label":"48 C.F.R. § 1.102","url":"https://www.ecfr.gov/current/title-48/section-1.102","by":{"2":"56"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":6,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"American Bankers Ass’n v. United States","cite":"932 F.3d 1375","y":2019,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/932/1375/","by":{"3":"53"}},{"t":"case","label":"American Fed’n of Gov’t Emps., AFL-CIO v. Federal Labor Relations Auth.","cite":"388 F.3d 405","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/388/405/","by":{"3":"21"}},{"t":"case","label":"Bowen v. Public Agencies Opposed to Social Sec. Entrapment","cite":"477 U.S. 41","y":1986,"id":"1985/85-521","sc":1,"sum":"Amended § 418(g) does not effect a taking of property within the meaning of the Fifth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"54"}},{"t":"case","label":"Community Health Choice, Inc. v. United States","cite":"141 Fed. Cl. 744","y":2019,"url":"https://www.courtlistener.com/c/Fed.%20Cl./141/744/","by":{"3":"34"}},{"t":"case","label":"Dahda v. United States","cite":"138 S. Ct. 1491","y":2018,"id":"2017/17-43","sc":1,"sum":"The Court decided that wiretap orders authorized by a judge for the federal district of Kansas in a government investigation of a suspected Kansas drug distribution ring were not facially insufficient because they did not lack any information that the wiretap statute required them to include, and because the challenged language permitting interception outside the court’s territorial jurisdiction was surplus.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Dodge v. Board of Educ.","cite":"302 U.S. 74","y":1937,"id":"scdb/1937-020","sc":1,"ar":1,"sum":"1. An Act merely fixing the terms or the tenures of public employees is presumptively not intended to create a vested right in the incumbent, but merely to declare a policy to be pursued until the legislature shall ordain otherwise.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"35, 54","5":"10"}},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"op":1,"sum":"The Court held that criminals who had committed drug crimes before the passage of the Fair Sentencing Act of 2010 but were sentenced after its passage were entitled to the sentencing provisions laid out in the Act.","sumSrc":"Oyez","by":{"3":"25"}},{"t":"case","label":"Hall v. Wisconsin","cite":"103 U.S. 5","y":1880,"id":"scdb/1880-017","sc":1,"by":{"3":"53"}},{"t":"case","label":"Indiana ex rel. Anderson v. Brand","cite":"303 U.S. 95","y":1938,"id":"scdb/1937-096","sc":1,"sum":"that, under the Act of 1927, the right of a permanent teacher to continued employment upon an indefinite contract was contractual, and the obligation of such a contract in the case of a township teacher was unconstitutionally impaired by the Act of 1033.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"54"}},{"t":"case","label":"Microsof t Corp. v. i4i Ltd. P’ship","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"sum":"The Court held that a challenge to a patent's validity must offer clear and convincing evidence.","sumSrc":"Oyez","by":{"3":"28"}},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"ar":1,"sum":"The Court held that the Appropriations Clause of the Constitution explicitly states that no money can be paid from the Treasury unless specifically authorized by a statute. Since there is a statute that denies Richmond his benefits, and there is not one that provides an exception, the Court held that Richmond’s receipt of incorrect information cannot affect the non-payment of his benefits.","sumSrc":"Oyez","by":{"3":"15, 20, 41","4":"5, 19","6":"13"}},{"t":"case","label":"Prairie County v. United States","cite":"782 F.3d 685","y":2015,"url":"https://www.courtlistener.com/c/F.3d/782/685/","sum":"Noting similar language in other legislation.","sumSrc":"brief:3","by":{"3":"28, 37","6":"13"}},{"t":"case","label":"Radzanower v. Touche Ross & Co.","cite":"426 U.S. 148","y":1976,"id":"1975/75-268","sc":1,"sum":"Venue in a suit against a national banking association charged with violating the Securities Exchange Act of 1934 held to be governed by the venue provision of the National Bank Act, 12 U. S. C. § 94, which provides that an action against a national banking association may be had in any federal district court within the district in which such association may be established, rather than by § 27 of the Securities …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"26","6":"14"}},{"t":"case","label":"Ricci v. DeStefano","cite":"557 U.S. 557","y":2009,"id":"2008/07-1428","sc":1,"sum":"The Court held that a municipality violated Title VII of the Civil Rights Act of 1964 when it rejected otherwise valid civil service exams because the results unintentionally prevented the promotion of minority candidates.","sumSrc":"Oyez","by":{"3":"26"}},{"t":"case","label":"Society for the Propagation of the Gospel v. Wheeler","cite":"22 F. Cas. 756","y":1814,"court":"C.C.D.N.H.","url":"https://www.courtlistener.com/c/F.%20Cas./22/756/","by":{"3":"52"}},{"t":"case","label":"Springdale Convalescent Ctr. v. Mathews","cite":"545 F.2d 943","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/545/943/","by":{"3":"31"}},{"t":"case","label":"United States v. Navajo Nation","cite":"556 U.S. 287","y":2009,"id":"2008/07-1410","sc":1,"op":5,"sum":"The Court held that its decision in Navajo I did not terminate the defendant's claim, however, the defendant did not provide sufficient sources of law and therefore the suit should be dismissed.","sumSrc":"Oyez","by":{"3":"15, 19, 29, 30","4":"22","5":"19","6":"19, 20"}},{"t":"case","label":"Usery v. Turner Elkhorn Mining Co.","cite":"428 U.S. 1","y":1976,"id":"1975/74-1302","sc":1,"sum":"Title IV of the Federal Coal Mine Health and Safety Act of 1969, as amended by the Black Lung Benefits Act of 1972, provides benefits to coal miners suffering from \"black lung disease\" (pneumoconiosis), and to survivors of miners who have died from, or while totally disabled by, the disease. Financial responsibility for payment of the benefits is divided into three parts: (1) Under Part B of Title IV claims filed …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"52"}},{"t":"case","label":"Wisconsin & Michigan Ry. Co. v. Powers","cite":"191 U.S. 379","y":1903,"id":"scdb/1903-030","sc":1,"sum":"A provision in a general tax law that railroads thereafter building and operating a road north of a certain parallel shall be exempted from the tax for ten years, unless the gross earnings shall exceed a certain sum, is not addressed as a covenant to such railroads and does not constitute a contract with them, the obligations of which cannot be impaired consistently with the Constitution of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"54","5":"10"}},{"t":"const","label":"Amendment V","clauses":[["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"3":"12"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"3":"32","4":"20"}},{"t":"usc","label":"31 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/31/1350","by":{"3":"9"}},{"t":"law","label":"Pub. L. No. 113-76","url":"https://www.govinfo.gov/link/plaw/113/public/76","by":{"3":"8, 9"}},{"t":"law","label":"Pub. L. No. 114-223","url":"https://www.govinfo.gov/link/plaw/114/public/223","by":{"3":"10"}},{"t":"law","label":"Pub. L. No. 95-480","url":"https://www.govinfo.gov/link/statute/92/1576","by":{"3":"31"}},{"t":"usc","label":"16 U.S.C. § 1531","url":"https://www.law.cornell.edu/uscode/text/16/1531","by":{"3":"51"}},{"t":"law","label":"Pub. L. No. 114-254","url":"https://www.govinfo.gov/link/plaw/114/public/254","by":{"3":"10"}},{"t":"usc","label":"28 U.S.C. § 1505","url":"https://www.law.cornell.edu/uscode/text/28/1505","by":{"3":"19"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(a)(2)"],"by":{"3":"19"}},{"t":"usc","label":"42 U.S.C. § 1395w-101","url":"https://www.law.cornell.edu/uscode/text/42/1395w-101","by":{"3":"31"}},{"t":"usc","label":"42 U.S.C. § 1396","url":"https://www.law.cornell.edu/uscode/text/42/1396","subs":["(1976)"],"by":{"3":"31"}},{"t":"usc","label":"42 U.S.C. § 1396b","url":"https://www.law.cornell.edu/uscode/text/42/1396b","subs":["(a)(1988)","(a)"],"stext":{"head":"§1396b. Payment to States","paras":[[0,"(a) Computation of amount"],[0,"From the sums appropriated therefor, the Secretary (except as otherwise provided in this section) shall pay to each State which has a plan approved under this subchapter, for each quarter, beginning with the quarter commencing January 1, 1966—"],[1,"(1) an amount equal to the Federal medical assistance percentage (as defined in section 1396d(b) of this title, subject to subsections (g) and (j) of this section and section 1396r–4(f) of this title) of the total amount expended during such quarter as medical assistance under the State plan; plus"],[1,"(2)(A) an amount equal to 75 per centum of so much of the sums expended during such quarter (as found necessary by the Secretary for the proper and efficient administration of the State plan) as are attributable to compensation or training of skilled professional medical personnel, and staff directly supporting such personnel, of the State agency or any other public agency; plus"],[1,"(B) notwithstanding paragraph (1) or subparagraph (A), with respect to amounts expended for nursing aide training and competency evaluation programs, and competency evaluation programs, described in section 1396r(e)(1) of this title (including the costs for nurse aides to complete such competency evaluation programs), regardless of whether the programs are provided in or outside nursing facilities or of the skill of the personnel involved in such programs, an amount equal to 50 percent (or, for calendar quarters beginning on or after July 1, 1988, and before October 1, 1990, the lesser of 90 percent or the Federal medical assistance percentage plus 25 percentage points) of so much of the sums expended during such quarter (as found necessary by the Secretary for the proper and efficient administration of the State plan) as are attributable to such programs; plus"],[1,"(C) an amount equal to 75 percent of so much of the sums expended during such quarter (as found necessary by the Secretary for the proper and efficient administration of the State plan) as are attributable to preadmission screening and resident review activities conducted by the State under section 1396r(e)(7) of this title; plus"],[1,"(D) for each calendar quarter during—"],[2,"(i) fiscal year 1991, an amount equal to 90 percent,"],[2,"(ii) fiscal year 1992, an amount equal to 85 percent,"],[2,"(iii) fiscal year 1993, an amount equal to 80 percent, and"],[2,"(iv) fiscal year 1994 and thereafter, an amount equal to 75 percent,"],[1,"of so much of the sums expended during such quarter (as found necessary by the Secretary for the proper and efficient administration of the State plan) as are attributable to State activities under section 1396r(g) of this title; plus"],[1,"(E) an amount equal to 75 percent of so much of the sums expended during such quarter (as found necessary by the Secretary for the proper and efficient administration of the State plan) as are attributable to translation or interpretation services in connection with the enrollment of, retention of, and use of services under this subchapter by, children of families for whom English is not the primary language; plus"],[1,"(3) an amount equal to—"],[2,"(A)(i) 90 per centum of so much of the sums expended during such quarter as are attributable to the design, development, or installation of such mechanized claims processing and information retrieval systems as the Secretary determines are likely to provide more efficient, economical, and effective administration of the plan and to be compatible with the claims processing and information retrieval systems utilized in the administration of subchapter XVIII, including the State's share of the cost of installing such a system to be used jointly in the administration of such State's plan and the plan of any other State approved under this subchapter,"],[2,"(ii) 90 per centum of so much of the sums expended during any such quarter in the fiscal year ending June 30, 1972, or the fiscal year ending June 30, 1973, as are attributable to the design, development, or installation of cost determination systems for State-owned general hospitals (except that the total amount paid to all States under this clause for either such fiscal year shall not exceed $150,000), and"],[2,"(iii) an amount equal to the Federal medical assistance percentage (as defined in section 1396d(b) of this title) of so much of the sums expended during such quarter (as found necessary by the Secretary for the proper and efficient administration of the State plan) as are attributable to such developments or modifications of systems of the type described in clause (i) as are necessary for the efficient collection and reporting on child health measures; and"],[2,"(B) 75 per centum of so much of the sums expended during such quarter as are attributable to the operation of systems (whether such systems are operated directly by the State or by another person under a contract with the State) of the type described in subparagraph (A)(i) (whether or not designed, developed, or installed with assistance under such subparagraph) which are approved by the Secretary and which include provision for prompt written notice to each individual who is furnished services covered by the plan, or to each individual in a sample group of individuals who are furnished such services, of the specific services (other than confidential services) so covered, the name of the person or persons furnishing the services, the date or dates on which the services were furnished, and the amount of the payment or payments made under the plan on account of the services; and"],[2,"(C)(i) 75 per centum of the sums expended with respect to costs incurred during such quarter (as found necessary by the Secretary for the proper and efficient administration of the State plan) as are attributable to the performance of medical and utilization review by a utilization and quality control peer review organization 1 or by an entity which meets the requirements of section 1320c–1 of this title, as determined by the Secretary, under a contract entered into under section 1396a(d) of this title; and"],[2,"(ii) 75 percent of the sums expended with respect to costs incurred during such quarter (as found necessary by the Secretary for the proper and efficient administration of the State plan) as are attributable to the performance of independent external reviews conducted under section 1396u–2(c)(2) of this title; and"],[2,"(D) 75 percent of so much of the sums expended by the State plan during a quarter in 1991, 1992, or 1993, as the Secretary determines is attributable to the statewide adoption of a drug use review program which conforms to the requirements of section 1396r–8(g) of this title;"],[2,"(E) 50 percent of the sums expended with respect to costs incurred during such quarter as are attributable to providing—"],[3,"(i) services to identify and educate individuals who are likely to be eligible for medical assistance under this subchapter and who have Sickle Cell Disease or who are carriers of the sickle cell gene, including education regarding how to identify such individuals; or"],[3,"(ii) education regarding the risks of stroke and other complications, as well as the prevention of stroke and other complications, in individuals who are likely to be eligible for medical assistance under this subchapter and who have Sickle Cell Disease; and"],[2,"(F)(i) 100 percent of so much of the sums expended during such quarter as are attributable to payments to Medicaid providers described in subsection (t)(1) to encourage the adoption and use of certified EHR technology; and"],[2,"(ii) 90 percent of so much of the sums expended during such quarter as are attributable to payments for reasonable administrative expenses related to the administration of payments described in clause (i) if the State meets the condition described in subsection (t)(9); plus"],[2,"(H)(i) 2 90 percent of the sums expended during the quarter as are attributable to the design, development, or installation of such mechanized verification and information retrieval systems as the Secretary determines are necessary to implement section 1396a(ee) of this title (including a system described in paragraph (2)(B) thereof), 3 and"],[2,"(ii) 75 percent of the sums expended during the quarter as are attributable to the operation of systems to which clause (i) applies,3 plus"],[1,"(4) an amount equal to 100 percent of the sums expended during the quarter which are attributable to the costs of the implementation and operation of the immigration status verification system described in section 1320b–7(d) of this title; plus"],[1,"(5) an amount equal to 90 per centum of the sums expended during such quarter which are attributable to the offering, arranging, and furnishing (directly or on a contract basis) of family planning services and supplies;"],[1,"(6) subject to subsection (b)(3), an amount equal to—"],[2,"(A) 90 per centum of the sums expended during such a quarter within the twelve-quarter period beginning with the first quarter in which a payment is made to the State pursuant to this paragraph, and"],[2,"(B) 75 per centum of the sums expended during each succeeding calendar quarter,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396b?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1396b. Payment to States","tname":"The Public Health and Welfare","by":{"3":"31, 32"}},{"t":"usc","label":"42 U.S.C. § 18001","url":"https://www.law.cornell.edu/uscode/text/42/18001","subs":["(g)(1)"],"by":{"3":"3, 5"}},{"t":"usc","label":"42 U.S.C. § 1396a","url":"https://www.law.cornell.edu/uscode/text/42/1396a","stext":{"head":"§1396a. State plans for medical assistance","paras":[[0,"(a) Contents"],[0,"A State plan for medical assistance must—"],[1,"(1) provide that it shall be in effect in all political subdivisions of the State, and, if administered by them, be mandatory upon them;"],[1,"(2) provide for financial participation by the State equal to not less than 40 per centum of the non-Federal share of the expenditures under the plan with respect to which payments under section 1396b of this title are authorized by this subchapter; and, effective July 1, 1969, provide for financial participation by the State equal to all of such non-Federal share or provide for distribution of funds from Federal or State sources, for carrying out the State plan, on an equalization or other basis which will assure that the lack of adequate funds from local sources will not result in lowering the amount, duration, scope, or quality of care and services available under the plan;"],[1,"(3) provide for granting an opportunity for a fair hearing before the State agency to any individual whose claim for medical assistance under the plan is denied or is not acted upon with reasonable promptness;"],[1,"(4) provide (A) such methods of administration (including methods relating to the establishment and maintenance of personnel standards on a merit basis, except that the Secretary shall exercise no authority with respect to the selection, tenure of office, and compensation of any individual employed in accordance with such methods, including provision for utilization of professional medical personnel in the administration and, where administered locally, supervision of administration of the plan, and, subject to section 1396b(i) of this title, including a specification that the single State agency described in paragraph (5) will ensure necessary transportation for beneficiaries under the State plan to and from providers and a description of the methods that such agency will use to ensure such transportation) as are found by the Secretary to be necessary for the proper and efficient operation of the plan, (B) for the training and effective use of paid subprofessional staff, with particular emphasis on the full-time or part-time employment of recipients and other persons of low income, as community service aides, in the administration of the plan and for the use of nonpaid or partially paid volunteers in a social service volunteer program in providing services to applicants and recipients and in assisting any advisory committees established by the State agency, (C) that each State or local officer, employee, or independent contractor who is responsible for the expenditure of substantial amounts of funds under the State plan, each individual who formerly was such an officer, employee, or contractor, and each partner of such an officer, employee, or contractor shall be prohibited from committing any act, in relation to any activity under the plan, the commission of which, in connection with any activity concerning the United States Government, by an officer or employee of the United States Government, an individual who was such an officer or employee, or a partner of such an officer or employee is prohibited by section 207 or 208 of title 18, and (D) that each State or local officer, employee, or independent contractor who is responsible for selecting, awarding, or otherwise obtaining items and services under the State plan shall be subject to safeguards against conflicts of interest that are at least as stringent as the safeguards that apply under chapter 21 of title 41 to persons described in section 2102(a)(3) of title 41;"],[1,"(5) either provide for the establishment or designation of a single State agency to administer or to supervise the administration of the plan; or provide for the establishment or designation of a single State agency to administer or to supervise the administration of the plan, except that the determination of eligibility for medical assistance under the plan shall be made by the State or local agency administering the State plan approved under subchapter I or XVI (insofar as it relates to the aged) if the State is eligible to participate in the State plan program established under subchapter XVI, or by the agency or agencies administering the supplemental security income program established under subchapter XVI or the State plan approved under part A of subchapter IV if the State is not eligible to participate in the State plan program established under subchapter XVI;"],[1,"(6) provide that the State agency will make such reports, in such form and containing such information, as the Secretary may from time to time require, and comply with such provisions as the Secretary may from time to time find necessary to assure the correctness and verification of such reports;"],[1,"(7) provide—"],[2,"(A) safeguards which restrict the use or disclosure of information concerning applicants and recipients to purposes directly connected with—"],[3,"(i) the administration of the plan; and"],[3,"(ii) the exchange of information necessary to certify or verify the certification of eligibility of children for free or reduced price breakfasts under the Child Nutrition Act of 1966 [42 U.S.C. 1771 et seq.] and free or reduced price lunches under the Richard B. Russell National School Lunch Act [42 U.S.C. 1751 et seq.], in accordance with section 9(b) of that Act [42 U.S.C. 1758(b)], using data standards and formats established by the State agency; and"],[2,"(B) that, notwithstanding the Express Lane option under subsection (e)(13), the State may enter into an agreement with the State agency administering the school lunch program established under the Richard B. Russell National School Lunch Act under which the State shall establish procedures to ensure that—"],[3,"(i) a child receiving medical assistance under the State plan under this subchapter whose family income does not exceed 133 percent of the poverty line (as defined in section 9902(2) of this title, including any revision required by such section), as determined without regard to any expense, block, or other income disregard, applicable to a family of the size involved, may be certified as eligible for free lunches under the Richard B. Russell National School Lunch Act and free breakfasts under the Child Nutrition Act of 1966 without further application; and"],[3,"(ii) the State agencies responsible for administering the State plan under this subchapter, and for carrying out the school lunch program established under the Richard B. Russell National School Lunch Act (42 U.S.C. 1751 et seq.) or the school breakfast program established by section 4 of the Child Nutrition Act of 1966 (42 U.S.C. 1773), cooperate in carrying out paragraphs (3)(F) and (15) of section 9(b) of that Act [42 U.S.C. 1758(b)];"],[1,"(8) provide that all individuals wishing to make application for medical assistance under the plan shall have opportunity to do so, and that such assistance shall be furnished with reasonable promptness to all eligible individuals;"],[1,"(9) provide—"],[2,"(A) that the State health agency, or other appropriate State medical agency (whichever is utilized by the Secretary for the purpose specified in the first sentence of section 1395aa(a) of this title), shall be responsible for establishing and maintaining health standards for private or public institutions in which recipients of medical assistance under the plan may receive care or services,"],[2,"(B) for the establishment or designation of a State authority or authorities which shall be responsible for establishing and maintaining standards, other than those relating to health, for such institutions,"],[2,"(C) that any laboratory services paid for under such plan must be provided by a laboratory which meets the applicable requirements of section 1395x(e)(9) of this title or paragraphs (16) and (17) of section 1395x(s) of this title, or, in the case of a laboratory which is in a rural health clinic, of section 1395x(aa)(2)(G) of this title, and"],[2,"(D) that the State maintain a consumer-oriented website providing useful information to consumers regarding all skilled nursing facilities and all nursing facilities in the State, including for each facility, Form 2567 State inspection reports (or a successor form), complaint investigation reports, the facility's plan of correction, and such other information that the State or the Secretary considers useful in assisting the public to assess the quality of long term care options and the quality of care provided by individual facilities;"],[1,"(10) provide—"],[2,"(A) for making medical assistance available, including at least the care and services listed in paragraphs (1) through (5), (13)(B), (17), (21), (28), (29), and (30) of section 1396d(a) of this title, to—"],[3,"(i) all individuals—"],[4,"(I) who are receiving aid or assistance under any plan of the State approved under subchapter I, X, XIV, or XVI, or part A or part E of subchapter IV (including individuals eligible under this subchapter by reason of section 602(a)(37),1 606(h),1 or 673(b) of this title, or considered by the State to be receiving such aid as authorized under section 682(e)(6)1 of this title),"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1396a. State plans for medical assistance","tname":"The Public Health and Welfare","by":{"3":"22","4":"15"}},{"t":"usc","label":"42 U.S.C. § 18021","url":"https://www.law.cornell.edu/uscode/text/42/18021","subs":["(a)(1)(B)"],"by":{"3":"5"}},{"t":"usc","label":"42 U.S.C. § 18041","url":"https://www.law.cornell.edu/uscode/text/42/18041","by":{"3":"6"}},{"t":"usc","label":"42 U.S.C. § 18043","url":"https://www.law.cornell.edu/uscode/text/42/18043","subs":["(c)"],"by":{"3":"6, 8, 15, 23"}},{"t":"usc","label":"2 U.S.C. § 622","url":"https://www.law.cornell.edu/uscode/text/2/622","subs":["(2)(A)(i)","(2)(A)(ii)","(9)"],"stext":{"head":"§622. Definitions","paras":[[0,"For purposes of this Act—"],[1,"(1) The terms \"budget outlays\" and \"outlays\" mean, with respect to any fiscal year, expenditures and net lending of funds under budget authority during such year."],[1,"(2) Budget authority and new budget authority.—"],[2,"(A) In general.—The term \"budget authority\" means the authority provided by Federal law to incur financial obligations, as follows:"],[3,"(i) provisions of law that make funds available for obligation and expenditure (other than borrowing authority), including the authority to obligate and expend the proceeds of offsetting receipts and collections;"],[3,"(ii) borrowing authority, which means authority granted to a Federal entity to borrow and obligate and expend the borrowed funds, including through the issuance of promissory notes or other monetary credits;"],[3,"(iii) contract authority, which means the making of funds available for obligation but not for expenditure; and"],[3,"(iv) offsetting receipts and collections as negative budget authority, and the reduction thereof as positive budget authority."],[2,"(B) Limitations on budget authority.—With respect to the Federal Hospital Insurance Trust Fund, the Supplementary Medical Insurance Trust Fund, the Unemployment Trust Fund, and the railroad retirement account, any amount that is precluded from obligation in a fiscal year by a provision of law (such as a limitation or a benefit formula) shall not be budget authority in that year."],[2,"(C) New budget authority.—The term \"new budget authority\" means, with respect to a fiscal year—"],[3,"(i) budget authority that first becomes available for obligation in that year, including budget authority that becomes available in that year s 1 a result of a reappropriation; or"],[3,"(ii) a change in any account in the availability of unobligated balances of budget authority carried over from a prior year, resulting from a provision of law first effective in that year;"],[2,"and includes a change in the estimated level of new budget authority provided in indefinite amounts by existing law."],[1,"(3) The term \"tax expenditures\" means those revenue losses attributable to provisions of the Federal tax laws which allow a special exclusion, exemption, or deduction from gross income or which provide a special credit, a preferential rate of tax, or a deferral of tax liability; and the term \"tax expenditures budget\" means an enumeration of such tax expenditures."],[1,"(4) The term \"concurrent resolution on the budget\" means—"],[2,"(A) a concurrent resolution setting forth the congressional budget for the United States Government for a fiscal year as provided in section 632 of this title; and"],[2,"(B) any other concurrent resolution revising the congressional budget for the United States Government for a fiscal year as described in section 635 of this title."],[1,"(5) The term \"appropriation Act\" means an Act referred to in section 105 of title 1."],[1,"(6) The term \"deficit\" means, with respect to a fiscal year, the amount by which outlays exceeds 2 receipts during that year."],[1,"(7) The term \"surplus\" means, with respect to a fiscal year, the amount by which receipts exceeds 2 outlays during that year."],[1,"(8) The term \"government-sponsored enterprise\" means a corporate entity created by a law of the United States that—"],[2,"(A)(i) has a Federal charter authorized by law;"],[2,"(ii) is privately owned, as evidenced by capital stock owned by private entities or individuals;"],[2,"(iii) is under the direction of a board of directors, a majority of which is elected by private owners;"],[2,"(iv) is a financial institution with power to—"],[3,"(I) make loans or loan guarantees for limited purposes such as to provide credit for specific borrowers or one sector; and"],[3,"(II) raise funds by borrowing (which does not carry the full faith and credit of the Federal Government) or to guarantee the debt of others in unlimited amounts; and"],[2,"(B)(i) does not exercise powers that are reserved to the Government as sovereign (such as the power to tax or to regulate interstate commerce);"],[2,"(ii) does not have the power to commit the Government financially (but it may be a recipient of a loan guarantee commitment made by the Government); and"],[2,"(iii) has employees whose salaries and expenses are paid by the enterprise and are not Federal employees subject to title 5."],[1,"(9) The term \"entitlement authority\" means—"],[2,"(A) the authority to make payments (including loans and grants), the budget authority for which is not provided for in advance by appropriation Acts, to any person or government if, under the provisions of the law containing that authority, the United States is obligated to make such payments to persons or governments who meet the requirements established by that law; and"],[2,"(B) the food stamp program."],[1,"(10) The term \"credit authority\" means authority to incur direct loan obligations or to incur primary loan guarantee commitments."],[1,"(11) The terms \"emergency\" and \"unanticipated\" have the meanings given to such terms in section 900(c) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/2/622?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§622. Definitions","tname":"The Congress","by":{"3":"21, 21, 21","6":"10"}},{"t":"usc","label":"25 U.S.C. § 450j-1","url":"https://www.law.cornell.edu/uscode/text/25/450j-1","subs":["(b)(2012)"],"by":{"3":"37"}},{"t":"usc","label":"31 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/31/701","subs":["(2)"],"by":{"3":"15, 21, 25, 28, 56"}},{"t":"usc","label":"31 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/31/1301","subs":["(d)"],"by":{"3":"15, 21, 25, 28, 56"}},{"t":"usc","label":"42 U.S.C. § 300gg-93","url":"https://www.law.cornell.edu/uscode/text/42/300gg-93","subs":["(e)"],"by":{"3":"7"}},{"t":"usc","label":"42 U.S.C. § 1395w-112","url":"https://www.law.cornell.edu/uscode/text/42/1395w-112","subs":["(b)"],"by":{"4":"14"}},{"t":"case","label":"Fed. Express Corp. v. Holowecki","cite":"552 U.S. 389","y":2008,"id":"2007/06-1322","sc":1,"op":1,"sum":"The Court, in a 7-2 opinion, upheld the Second Circuit, stating that the procedure used to file the document was consistent with the design and purpose of the ADEA.","sumSrc":"Oyez","by":{"5":"11"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"op":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"5":"17"}},{"t":"case","label":"Me. Cmty. Health Options v. United States","cite":"133 Fed. Cl. 1","y":2017,"url":"https://www.courtlistener.com/c/Fed.%20Cl./133/1/","op":1,"by":{"5":"11"}},{"t":"case","label":"Community Health Choice, Inc. v. United States","cite":"141 Fed.Cl. 744","y":2019,"url":"https://www.courtlistener.com/c/Fed.Cl./141/744/","by":{"6":"18"}},{"t":"case","label":"Conway v. United States","cite":"2019 WL 4877280","y":2019,"court":"Fed.Cl. Oct. 3","by":{"6":"19"}},{"t":"case","label":"Dougherty v. United States","cite":"18 Ct.Cl. 496","y":1883,"url":"https://www.courtlistener.com/c/Ct.Cl./18/496/","by":{"6":"12"}},{"t":"case","label":"Farmer v. United States","cite":"2018 WL 1365797","y":2018,"court":"D.S.C. Mar. 16","by":{"6":"18"}},{"t":"case","label":"Ferris v. United States","cite":"27 Ct.Cl. 542","y":1892,"url":"https://www.courtlistener.com/c/Ct.Cl./27/542/","op":1,"by":{"6":"12, 24"}},{"t":"case","label":"Fry v. Centers for Medicare and Medicaid Services","cite":"2019 WL 3801822","y":2019,"court":"N.D. Ill. Aug. 13","op":2,"by":{"6":"18, 21"}},{"t":"case","label":"Gerhart v. United States Dep’t of Health & Human Servs.","cite":"242 F. Supp. 3d 806","y":2017,"court":"S.D. Iowa","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/242/806/","by":{"6":"18"}},{"t":"case","label":"Glidden Co. v. Zdanok","cite":"370 U.S. 530","y":1962,"id":"1961/242","sc":1,"sum":"The Court held that judges in the United States Court of Claims and the United States Court of Customs and Patent Appeals constitutionally protected in tenure and compensation under Article III of the Constitution.","sumSrc":"Oyez","by":{"6":"11"}},{"t":"case","label":"Lebron v. Nat’l R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"6":"25"}},{"t":"case","label":"Lovett v. United States","cite":"104 Ct.Cl. 557","y":1945,"url":"https://www.courtlistener.com/c/Ct.Cl./104/557/","by":{"6":"11"}},{"t":"case","label":"New York Central R.R. Co. v. United States","cite":"65 Ct.Cl. 115","y":1928,"url":"https://www.courtlistener.com/c/Ct.Cl./65/115/","by":{"6":"11"}},{"t":"case","label":"Pennsylvania Dept. of Corrections v. Yeskey","cite":"524 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"sum":"The Court held that under the ADA no \"public entity\" may discriminate against qualified disabled individuals due to their disability. Moreover, the Court stated that the ADA's protections extended to cover prison inmates as well as any other liberated citizen.","sumSrc":"Oyez","by":{"6":"20"}},{"t":"case","label":"Peralta v. Heights Medical Center, Inc.","cite":"485 U.S. 80","y":1988,"id":"1987/86-1430","sc":1,"sum":"The holding below contravenes this Court's precedents, under which a judgment entered without notice or service violates the Due Process Clause. See, e. g., Mullane v. Central Hanover Bank & Trust Co., 339 U. S. 306; Armstrong v. Manzo, 380 U. S. 545. The argument that appellant suffered no harm from the default judgment since the same judgment would again be entered on retrial absent a meritorious defense is …","sumSrc":"Syllabus (U.S. Reports)","by":{"6":"18"}},{"t":"case","label":"R.A.V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"op":1,"sum":"The Court found a Minnesota ordinance violated the First Amendment because the ordinance was overly broad in the content-based speech it prohibited.","sumSrc":"Oyez","by":{"6":"26"}},{"t":"case","label":"Republic Nat’l Bank of Miami v. United States","cite":"506 U.S. 80","y":1992,"id":"1992/91-767","sc":1,"op":1,"sum":"The Government filed a civil action in the District Court, alleging that a particular residence was subject to forfeiture under 21 U. S. C. §881(a)(6) because its owner had purchased it with narcotics trafficking proceeds. After the United States Marshal seized the property, petitioner Bank, which claimed a lien under a recorded mortgage, agreed to the Government's request for a sale of the property, the proceeds of …","sumSrc":"Syllabus (U.S. Reports)","by":{"6":"12"}},{"t":"case","label":"Richardson v. United States Dep’t of Health & Human Servs.","cite":"2018 WL 1569772","y":2018,"court":"D. Nev. Mar. 30","by":{"6":"18"}},{"t":"case","label":"Train v. City of New York","cite":"420 U.S. 35","y":1975,"id":"1974/73-1377","sc":1,"sum":"The 1972 Amendments do not permit the Administrator to allot to the States under § 205 (a) less than the entire amounts authorized to be appropriated by § 207.","sumSrc":"Syllabus (U.S. Reports)","by":{"6":"10, 20"}},{"t":"case","label":"U.S. House of Representatives v. Burwell","cite":"2015 WL 9316243","y":2015,"court":"D.D.C. Dec. 2","ar":2,"by":{"6":"2"}},{"t":"case","label":"United States v. Emery, Bird, Thayer Realty Co.","cite":"237 U.S. 28","y":1915,"id":"scdb/1914-056","sc":1,"sum":"The District Court, sitting as a Court of Claims, under § 24 (20 subd.) has jurisdiction over claims against the United States for refunding taxes paid under the Corporation Tax law under duress and protest to the Collector and by him turned over to the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"6":"4"}},{"t":"case","label":"United States v. White Mountain Apache Tribe","cite":"537 U.S. 465","y":2003,"id":"2002/01-1067","sc":1,"op":3,"ar":3,"sum":"The Court held that Public Law 86-392 gives rise to Indian Tucker Act jurisdiction in the Court of Federal Claims over the Tribe's suit.","sumSrc":"Oyez","by":{"6":"20"}},{"t":"usc","label":"5 U.S.C. § 5942","url":"https://www.law.cornell.edu/uscode/text/5/5942","by":{"6":"20"}},{"t":"usc","label":"37 U.S.C. § 204","url":"https://www.law.cornell.edu/uscode/text/37/204","by":{"6":"20"}},{"t":"reg","label":"42 C.F.R. § 422.458","url":"https://www.ecfr.gov/current/title-42/section-422.458","by":{"6":"8, 4"}},{"t":"reg","label":"67 Fed. Reg. 41,070","url":"https://www.govinfo.gov/link/fr/67/41070","by":{"6":"8"}},{"t":"reg","label":"77 Fed. Reg. 17,236","url":"https://www.govinfo.gov/link/fr/77/17236","by":{"6":"7"}},{"t":"reg","label":"78 Fed. Reg. 15,412","url":"https://www.govinfo.gov/link/fr/78/15412","by":{"6":"7"}},{"t":"usc","label":"42 U.S.C. § 1395w","url":"https://www.law.cornell.edu/uscode/text/42/1395w","by":{"6":"4"}}]};